window.CURRICULUM_3 = [{"id":"whatsname3","index":0,"name":"What's in a Name?","subtitle":"Tally marks, number names and sorting","emoji":"🏷️","palette":{"from":"#fbbf24","to":"#92400e"},"lessons":[{"id":"wn1","title":"Marks on the Wall","icon":"🐄","kind":"lesson","story":"Deba and Deep take their cows out to graze. They cannot count, so they need a clever trick!","teach":[{"title":"One mark for each cow","body":"When a cow goes out, make one mark on the wall. One cow, one mark!","visual":"🐄"},{"title":"Strike out when they return","body":"When a cow comes back, strike out one mark. If no marks are left, all cows are home!","visual":"✅"}],"questions":[{"kind":"numeric","prompt":"Deep makes 7 marks: ||||||| . Then 4 cows come back and he strikes out 4 marks. How many marks are left?","answer":3,"explain":"7 marks take away 4 struck out leaves 3 marks."},{"kind":"mcq","prompt":"Two marks are still left on the wall. What does that mean?","options":["Two extra cows came home","Two cows have not come back yet","The wall is broken","All the cows are home"],"answer":1,"explain":"A mark that is not struck out means a cow has not returned."},{"kind":"numeric","prompt":"Hemant has 36 cows and 23 sheep. How many marks does he make for all his animals?","answer":59,"explain":"36 + 23 = 59 marks, one for each animal."},{"kind":"numeric","prompt":"12 cows go out, so Deba makes 12 marks. 9 cows come back. How many cows are still out?","answer":3,"explain":"12 - 9 = 3 cows are still out."}]},{"id":"wn2","title":"Animal Team Captains","icon":"🐯","kind":"lesson","story":"The animals are picking team captains! The longest name and the shortest name will lead.","teach":[{"title":"Count the letters","body":"A name's length is how many letters it has. 'deer' has 4 letters: d, e, e, r.","visual":"🔤"},{"title":"Longest and shortest","body":"The longest name has the most letters. The shortest name has the fewest letters.","visual":"📏"}],"questions":[{"kind":"numeric","prompt":"How many letters are in the name 'elephant'?","answer":8,"explain":"e-l-e-p-h-a-n-t has 8 letters."},{"kind":"mcq","prompt":"Which name is the longest: tiger, deer, monkey or ox?","options":["deer","ox","tiger","monkey"],"answer":3,"explain":"monkey has 6 letters, tiger 5, deer 4 and ox 2."},{"kind":"mcq","prompt":"Which name is the shortest: dog, rat, ox or lion?","options":["ox","dog","lion","rat"],"answer":0,"explain":"ox has only 2 letters. The others have 3 or 4."},{"kind":"numeric","prompt":"Mahesh has 6 letters in his name. Karthik has 7. How many more letters does Karthik's name have?","answer":1,"explain":"7 - 6 = 1 more letter."}]},{"id":"wn3","title":"Number Name Cards","icon":"🃏","kind":"lesson","story":"Teji and Jojo build numbers with name cards. Let us count the letters in each number name!","teach":[{"title":"Numbers have names too","body":"56 is 'fifty-six'. Fifty has 5 letters and six has 3, so it has 8 letters.","visual":"🔢"},{"title":"Add the two parts","body":"For a two-word name, count the letters in each word. Then add them. 'forty-three' is 5 + 5 = 10.","visual":"➕"}],"questions":[{"kind":"numeric","prompt":"How many letters are in 'seventeen' (17)?","answer":9,"explain":"s-e-v-e-n-t-e-e-n has 9 letters."},{"kind":"numeric","prompt":"How many letters are in 'thirty-five' (35)? Add thirty (6) and five (4).","answer":10,"explain":"6 + 4 = 10 letters."},{"kind":"mcq","prompt":"Which number has a name with only 3 letters?","options":["6","9","8","7"],"answer":0,"explain":"six has 3 letters. seven and eight have 5. nine has 4."},{"kind":"mcq","prompt":"My name is 'ninety' plus a word with 4 letters. My number is more than 95. Who am I?","options":["99","94","90","95"],"answer":0,"explain":"ninety-nine: nine has 4 letters, and 99 is more than 95."}]},{"id":"wn4","title":"Sorting Things","icon":"🧺","kind":"lesson","story":"Teji and Jojo have many picture cards. They sort the same cards in different ways!","teach":[{"title":"Make groups","body":"We can put things in groups. Teji made 'eat food' and 'do not eat food'.","visual":"🧺"},{"title":"Many ways to group","body":"The same things can be grouped in different ways. Jojo used 'needs electricity' and 'does not need electricity'.","visual":"💡"}],"questions":[{"kind":"mcq","prompt":"Which one does NOT need electricity: TV, Fan, Lamp or Pillow?","options":["Pillow","TV","Fan","Lamp"],"answer":0,"explain":"A pillow works without electricity."},{"kind":"mcq","prompt":"TV, Fan, Lamp and Bed. Which one does not belong in 'needs electricity'?","options":["Lamp","TV","Fan","Bed"],"answer":3,"explain":"A bed does not need electricity."},{"kind":"mcq","prompt":"Cow, hen, dog and stone. Which one does not eat food?","options":["dog","stone","cow","hen"],"answer":1,"explain":"A stone is not alive, so it does not eat."},{"kind":"numeric","prompt":"There are 10 cards. 6 need electricity. How many do not need electricity?","answer":4,"explain":"10 - 6 = 4 cards."}]},{"id":"wn5","title":"Count and Compare","icon":"💇","kind":"lesson","story":"Mala looks at her classmates. Everyone has a different name and hair style! Let us count them.","teach":[{"title":"Starting and ending letters","body":"Look at the first letter and the last letter of each name. Count names that match.","visual":"🔠"},{"title":"Write a table","body":"Write each hair style and how many children have it. Then add to find all the children.","visual":"📋"}],"questions":[{"kind":"numeric","prompt":"Names: Asha, Anil, Bina, Chitra, Arun, Dev. How many names start with A?","answer":3,"explain":"Asha, Anil and Arun start with A, so 3."},{"kind":"numeric","prompt":"Names: Asha, Anil, Bina, Chitra, Arun, Dev. How many names end with the letter a?","answer":3,"explain":"Asha, Bina and Chitra end with a, so 3."},{"kind":"mcq","prompt":"Names: Asha, Anil, Bina, Chitra, Arun, Dev. Which letter starts the most names?","options":["B","A","C","D"],"answer":1,"explain":"A starts 3 names. B, C and D start 1 each."},{"kind":"numeric","prompt":"In Mala's class, 7 children have ponytails, 5 have braids and 4 have open hair. How many children in all?","answer":16,"explain":"7 + 5 + 4 = 16 children."}]},{"id":"wn-boss","title":"The Muddle Cow","icon":"🐮","kind":"boss","boss":{"name":"The Muddle Cow","taunt":"Moo! Can you keep track of everything?"},"story":"The Muddle Cow has mixed up the marks, the names and the cards! Fix it all, little explorer.","teach":[{"title":"Count, compare and group","body":"Use marks to count, letters to compare names, and groups to sort things.","visual":"🏷️"}],"questions":[{"kind":"numeric","prompt":"Deba makes 9 marks for 9 cows. 6 cows come back and 6 marks are struck out. How many marks are left?","answer":3,"explain":"9 - 6 = 3 marks are left."},{"kind":"mcq","prompt":"Which name is the longest: rat, tiger, elephant or goat?","options":["elephant","tiger","goat","rat"],"answer":0,"explain":"elephant has 8 letters, the most."},{"kind":"numeric","prompt":"How many letters are in 'fifty-six' (56)?","answer":8,"explain":"fifty has 5 letters and six has 3, so 8."},{"kind":"mcq","prompt":"Which number name has more letters: seven (7) or six (6)?","options":["Same","six (6)","Cannot tell","seven (7)"],"answer":3,"explain":"seven has 5 letters and six has 3."},{"kind":"mcq","prompt":"Fan, Lamp, TV and Pillow. Which one does not need electricity?","options":["TV","Fan","Pillow","Lamp"],"answer":2,"explain":"A pillow needs no electricity."},{"kind":"numeric","prompt":"Hemant has 36 cows and 23 sheep. How many animals does he have?","answer":59,"explain":"36 + 23 = 59 animals."}]}]},{"id":"toyjoy3","index":1,"name":"Toy Joy","subtitle":"Solid shapes: faces, edges, corners","emoji":"🧸","palette":{"from":"#60a5fa","to":"#1e3a8a"},"lessons":[{"id":"tj1","title":"Meet the Shape Friends","icon":"🧸","kind":"lesson","story":"Welcome to the toy shop, Explorer! Jaya builds rockets and houses from shapes. Can you name them all?","teach":[{"title":"Five shape friends","body":"Cube, cuboid, cylinder, cone and sphere are solid shapes. Toys are built from them.","visual":"🧸"},{"title":"Shapes around us","body":"A dice 🎲 is a cube. A brick 🧱 is a cuboid. A can 🥫 is a cylinder. A ball ⚽ is a sphere.","visual":"🎲"}],"questions":[{"kind":"mcq","prompt":"Which shape is a dice 🎲?","options":["Cube","Sphere","Cylinder","Cone"],"answer":0,"explain":"A dice has six equal square faces, so it is a cube."},{"kind":"mcq","prompt":"A ball ⚽ looks like which shape?","options":["Cuboid","Cone","Cube","Sphere"],"answer":3,"explain":"A ball is round all over. That is a sphere."},{"kind":"mcq","prompt":"A tin can 🥫 looks like which shape?","options":["Cube","Cone","Sphere","Cylinder"],"answer":3,"explain":"A can has two flat circles and a curved side. That is a cylinder."},{"kind":"mcq","prompt":"A matchbox or a brick 🧱 looks like which shape?","options":["Cylinder","Cuboid","Cone","Sphere"],"answer":1,"explain":"A brick has flat faces and is longer on one side. That is a cuboid."}]},{"id":"tj2","title":"Faces, Edges and Corners","icon":"📦","kind":"lesson","story":"Jaya is drawing animal faces on old boxes. She needs the parts of each box. Help her name them!","teach":[{"title":"Three parts","body":"A face is a side of a shape. An edge is where two faces meet. A corner is where edges meet.","visual":"📦"},{"title":"The cube","body":"A cube has 6 faces, 12 edges and 8 corners. A cube is a special type of cuboid.","visual":"🎲"}],"questions":[{"kind":"numeric","prompt":"How many faces does a cube have? 🎲","answer":6,"explain":"A cube has 6 flat faces, like the 6 sides of a dice."},{"kind":"numeric","prompt":"How many corners does a cube have? 🎲","answer":8,"explain":"A cube has 8 corners, 4 on the top and 4 on the bottom."},{"kind":"numeric","prompt":"How many edges does a cube have? 🎲","answer":12,"explain":"A cube has 12 edges: 4 on top, 4 on the bottom and 4 on the sides."},{"kind":"mcq","prompt":"What do we call the line where two faces of a box meet?","options":["Face","Edge","Circle","Corner"],"answer":1,"explain":"Two faces meet at an edge."}]},{"id":"tj3","title":"Flat or Curved?","icon":"🥫","kind":"lesson","story":"The toy shop owner asks a riddle: which toys roll, and which toys slide? Look at the faces to find out!","teach":[{"title":"Flat faces","body":"A cube and a cuboid have only flat faces. They have straight edges and corners.","visual":"📦"},{"title":"Curved faces","body":"A sphere has only one curved face and no edges. A cylinder and a cone have both flat and curved faces.","visual":"⚽"}],"questions":[{"kind":"mcq","prompt":"Which shape has no edges?","options":["Cuboid","Sphere","Cylinder","Cube"],"answer":1,"explain":"A sphere is smooth and round, so it has no edges."},{"kind":"mcq","prompt":"Which shape has only flat faces?","options":["Cylinder","Cone","Sphere","Cuboid"],"answer":3,"explain":"A cuboid has 6 flat faces and no curved face."},{"kind":"mcq","prompt":"Which shape has only a curved face?","options":["Cuboid","Cone","Cube","Sphere"],"answer":3,"explain":"A sphere has just one curved face."},{"kind":"numeric","prompt":"How many flat faces does a cylinder 🥫 have?","answer":2,"explain":"A cylinder has 2 flat circles, one on top and one at the bottom."}]},{"id":"tj4","title":"Build and Describe","icon":"🚀","kind":"lesson","story":"Jaya is building a rocket from different shapes. Tell her which shape goes where and how many she used!","teach":[{"title":"Where is it?","body":"We say on top of, under and between to tell where a shape is placed.","visual":"🏗️"},{"title":"Count each shape","body":"To count toy parts, count each kind of shape one by one. Then add them up.","visual":"🚂"}],"questions":[{"kind":"mcq","prompt":"A cone sits on top of a cylinder. The cylinder sits on a cube. Which shape is on the very top?","options":["Cube","Cone","Sphere","Cylinder"],"answer":1,"explain":"The cone is at the top of the pile."},{"kind":"mcq","prompt":"A cube is at the bottom, a cylinder is in the middle, and a cone is on top. Which shape is between the other two?","options":["Cylinder","Cube","Cone","Sphere"],"answer":0,"explain":"The cylinder is in the middle, between the cube and the cone."},{"kind":"numeric","prompt":"Devika's toy engine has 2 red cylinders, 3 yellow cones, 1 grey cuboid and 4 blue cubes. How many shapes in all?","answer":10,"explain":"2 + 3 + 1 + 4 = 10 shapes."},{"kind":"numeric","prompt":"Jaya's rocket has 1 cone, 2 cylinders and 3 cubes. How many shapes did she use?","answer":6,"explain":"1 + 2 + 3 = 6 shapes."}]},{"id":"tj5","title":"Dice and Cube Towers","icon":"🎲","kind":"lesson","story":"Time to play with dice! Roll them, turn them, and stack cubes to build towers and walls.","teach":[{"title":"Opposite faces on a dice","body":"On a dice, 1 is opposite 6, 2 is opposite 5, and 3 is opposite 4. Each opposite pair adds up to 7.","visual":"🎲"},{"title":"Joining cubes","body":"We can join cubes in many ways. Count every cube in a tower or a wall.","visual":"🧱"}],"questions":[{"kind":"numeric","prompt":"A dice shows 1 on the top. What number is on the face opposite it, at the bottom?","answer":6,"explain":"1 and 6 are on opposite faces."},{"kind":"numeric","prompt":"What number is opposite 4 on a dice?","answer":3,"explain":"4 and 3 are opposite, and 4 + 3 = 7."},{"kind":"numeric","prompt":"What do the numbers on opposite faces of a dice add up to?","answer":7,"explain":"1 + 6 = 7, 2 + 5 = 7 and 3 + 4 = 7."},{"kind":"numeric","prompt":"A cube wall has 2 rows. Each row has 3 cubes 🧊🧊🧊. How many cubes are in the wall?","answer":6,"explain":"2 rows of 3 cubes make 3 + 3 = 6 cubes."}]},{"id":"tj-boss","title":"The Toy Tower Boss","icon":"🏰","kind":"boss","boss":{"name":"Wobbly Tower","taunt":"Name my shapes and I will stop wobbling!"},"story":"A giant toy tower wobbles in the shop! Use all your shape skills to make it stand still.","teach":[{"title":"Shape review","body":"Cubes and cuboids have flat faces. Cylinders and cones have flat and curved faces. A sphere has only a curved face.","visual":"🧸"}],"questions":[{"kind":"mcq","prompt":"A party hat that is pointed on top looks like which shape?","options":["Cone","Cube","Sphere","Cylinder"],"answer":0,"explain":"A pointed hat with a round bottom is a cone."},{"kind":"mcq","prompt":"Which shape has both flat and curved faces?","options":["Cube","Sphere","Cylinder","Cuboid"],"answer":2,"explain":"A cylinder has 2 flat faces and 1 curved face."},{"kind":"numeric","prompt":"How many corners does a cube have? 🎲","answer":8,"explain":"A cube has 8 corners."},{"kind":"numeric","prompt":"How many faces do 2 cubes have all together? 🎲🎲","answer":12,"explain":"6 + 6 = 12 faces."},{"kind":"numeric","prompt":"What number is opposite 2 on a dice?","answer":5,"explain":"2 and 5 are opposite, and 2 + 5 = 7."},{"kind":"numeric","prompt":"A cube staircase has 1 cube on the top step. The middle has 2 and the bottom has 3. How many cubes in all?","answer":6,"explain":"1 + 2 + 3 = 6 cubes."}]}]},{"id":"doublecentury3","index":2,"name":"Double Century","subtitle":"Numbers up to 200","emoji":"🏏","palette":{"from":"#fb923c","to":"#7c2d12"},"lessons":[{"id":"dcn1","title":"The Talking Pot","icon":"🏺","kind":"lesson","story":"Bholu finds a Talking Pot at the cricket mela. It says the next number after any number you say!","teach":[{"title":"One more","body":"Say 42 and the Pot says 43. The next number is always one more.","visual":"🏺"},{"title":"A century!","body":"One more than 99 is 100. Ten bundles of 10 sticks make 100. A batter who scores 100 runs scores a century!","visual":"🏏"}],"questions":[{"kind":"numeric","prompt":"Bholu says 39. What does the Talking Pot say?","answer":40,"explain":"One more than 39 is 40."},{"kind":"numeric","prompt":"Bholu says 63. What does the Talking Pot say?","answer":64,"explain":"One more than 63 is 64."},{"kind":"numeric","prompt":"The Pot says 90. What number did Bholu say?","answer":89,"explain":"The Pot says one more, so Bholu said 89."},{"kind":"mcq","prompt":"Ten bundles of 10 sticks each make how many sticks? 🪵","options":["90","100","110","10"],"answer":1,"explain":"10 tens make 100."}]},{"id":"dcn2","title":"Making 100","icon":"💯","kind":"lesson","story":"Rani hops along a number line to reach 100 at the finish line. Help her pick the right jumps!","teach":[{"title":"Two parts make 100","body":"Bholu was on 65 and jumped 35 more. 65 and 35 make 100.","visual":"🦘"},{"title":"Tens help","body":"60 and 40 make 100. 70 and 30 make 100. Think of tens to find the other part.","visual":"🔟"}],"questions":[{"kind":"numeric","prompt":"60 and 40 make how many?","answer":100,"explain":"6 tens and 4 tens make 10 tens, which is 100."},{"kind":"numeric","prompt":"45 and ___ make 100. Find the missing number.","answer":55,"explain":"100 minus 45 is 55."},{"kind":"numeric","prompt":"___ and 25 make 100. Find the missing number.","answer":75,"explain":"100 minus 25 is 75."},{"kind":"mcq","prompt":"Which pair makes 100?","options":["70 and 20","60 and 30","70 and 30","80 and 30"],"answer":2,"explain":"70 + 30 = 100."}]},{"id":"dcn3","title":"Beyond 100","icon":"🚀","kind":"lesson","story":"Lina keeps counting past 100 at the mela. 101, 102, 103... where will she stop?","teach":[{"title":"100 and more","body":"100 and 1 makes 101, one hundred one. 100 and 5 makes 105, one hundred five.","visual":"➕"},{"title":"Number names","body":"100 and 10 makes 110, one hundred ten. 100 and 9 makes 109, one hundred nine.","visual":"📝"}],"questions":[{"kind":"numeric","prompt":"100 and 3 makes which number?","answer":103,"explain":"100 and 3 more makes 103."},{"kind":"numeric","prompt":"100 and 7 makes which number?","answer":107,"explain":"100 and 7 more makes 107."},{"kind":"mcq","prompt":"How do we say 106?","options":["Sixteen hundred","One hundred sixty","One hundred sixteen","One hundred six"],"answer":3,"explain":"106 is 100 and 6, so one hundred six."},{"kind":"mcq","prompt":"Which number is one hundred ten?","options":["11","110","101","100"],"answer":1,"explain":"One hundred ten is 100 and 10, which is 110."}]},{"id":"dcn4","title":"Bundles and Sticks","icon":"🪵","kind":"lesson","story":"Bholu packs matchsticks into bundles of 10 and one big bundle of 100. Count them with him!","teach":[{"title":"100s, 10s and 1s","body":"123 has 1 hundred, 2 tens and 3 ones. One bundle of 100, two bundles of 10, three loose sticks.","visual":"🪵"},{"title":"Clap, snap and pat","body":"A clap is 100, a snap is 10 and a pat is 1. Clap, snap snap, pat pat pat is 123.","visual":"👏"}],"questions":[{"kind":"numeric","prompt":"1 hundred, 2 tens and 5 ones make which number?","answer":125,"explain":"100 + 20 + 5 = 125."},{"kind":"numeric","prompt":"Look at 147. How many tens are in it?","answer":4,"explain":"147 has 1 hundred, 4 tens and 7 ones."},{"kind":"numeric","prompt":"Look at 138. How many ones are in it?","answer":8,"explain":"138 has 1 hundred, 3 tens and 8 ones."},{"kind":"mcq","prompt":"Clap, snap snap snap, pat pat. Which number is this? 👏🫰🫰🫰👋👋","options":["123","231","1032","132"],"answer":3,"explain":"1 clap is 100, 3 snaps are 30, 2 pats are 2. That is 132."}]},{"id":"dcn5","title":"One More, One Less","icon":"↔️","kind":"lesson","story":"The Talking Pot is back! This time Lina must find the numbers just before and after.","teach":[{"title":"Before and after","body":"One less than 160 is 159. One more than 160 is 161.","visual":"↔️"},{"title":"On the number line","body":"On a number line, numbers grow to the right. 125 is halfway between 120 and 130.","visual":"📏"}],"questions":[{"kind":"numeric","prompt":"What is one more than 129?","answer":130,"explain":"One more than 129 is 130."},{"kind":"numeric","prompt":"What is one less than 187?","answer":186,"explain":"One less than 187 is 186."},{"kind":"numeric","prompt":"What is one less than 134?","answer":133,"explain":"One less than 134 is 133."},{"kind":"mcq","prompt":"Which number is between 148 and 150?","options":["147","149","151","159"],"answer":1,"explain":"149 comes after 148 and before 150."}]},{"id":"dcn6","title":"Jump to 200","icon":"🏏","kind":"lesson","story":"Rani is on 150 runs and wants a double century. A double century is 200! Which jumps will get her there?","teach":[{"title":"Double century","body":"Two hundreds make 200. 150 + 50 = 200 and 140 + 60 = 200.","visual":"🏏"},{"title":"Skip jumps","body":"Jumps of 20 from 100 go 120, 140, 160, 180, 200. Jumps of 5 from 100 go 105, 110, 115.","visual":"🦘"}],"questions":[{"kind":"numeric","prompt":"Rani has 150 runs. How many more runs make 200?","answer":50,"explain":"150 + 50 = 200."},{"kind":"numeric","prompt":"140 and ___ make 200. Find the missing number.","answer":60,"explain":"140 + 60 = 200."},{"kind":"numeric","prompt":"Jumps of 20 from 100: 120, 140, 160, ___. What comes next?","answer":180,"explain":"160 + 20 = 180."},{"kind":"numeric","prompt":"Jumps of 5 from 100: 105, 110, 115, ___. What comes next?","answer":120,"explain":"115 + 5 = 120."}]},{"id":"dcn-boss","title":"Double Century Challenge","icon":"🏆","kind":"boss","boss":{"name":"Captain Century","taunt":"Can you score a double century with me?"},"story":"Captain Century wants you to prove your number skills. Score 200 runs and win the cricket cup!","teach":[{"title":"Review","body":"10 tens make 100. Two hundreds make 200. Use hundreds, tens and ones to read any number up to 200.","visual":"🏆"}],"questions":[{"kind":"numeric","prompt":"The Pot says 100. What number did Bholu say?","answer":99,"explain":"The Pot says one more, so Bholu said 99."},{"kind":"numeric","prompt":"35 and ___ make 100. Find the missing number.","answer":65,"explain":"100 minus 35 is 65."},{"kind":"mcq","prompt":"How do we say 154?","options":["Fifty four","One hundred four","One hundred fifty four","One hundred forty five"],"answer":2,"explain":"154 is 100 and 54, so one hundred fifty four."},{"kind":"numeric","prompt":"1 hundred, 6 tens and 2 ones make which number?","answer":162,"explain":"100 + 60 + 2 = 162."},{"kind":"numeric","prompt":"What is one more than 199?","answer":200,"explain":"One more than 199 is 200, a double century."},{"kind":"numeric","prompt":"160 and ___ make 200. Find the missing number.","answer":40,"explain":"160 + 40 = 200."},{"kind":"mcq","prompt":"Count in jumps of 20: 100, 120, 140. Which number comes next?","options":["180","160","150","170"],"answer":1,"explain":"140 + 20 = 160."}]}]},{"id":"nanimaa3","index":3,"name":"Vacation with My Nani Maa","subtitle":"Add and subtract to 100+","emoji":"🚂","palette":{"from":"#f472b6","to":"#831843"},"lessons":[{"id":"nm1","title":"Nani Maa's Magic Trick","icon":"🎩","kind":"lesson","story":"Chirag and Nandini reach Nani Maa's village. Nani Maa hides some seeds under a handkerchief!","teach":[{"title":"Find the hidden seeds","body":"Total seeds minus seeds on the table gives the hidden seeds. If 15 seeds in all and 12 are on the table, 3 are hidden.","visual":"🌰"},{"title":"Make 9, 10 and 20","body":"Nani Maa says a number, you say the one that makes 9. For 4, you say 5.","visual":"🎩"}],"questions":[{"kind":"numeric","prompt":"There are 15 seeds in all. 12 seeds are on the table. How many seeds are hidden? 🌰","answer":3,"explain":"15 - 12 = 3 seeds are hidden."},{"kind":"numeric","prompt":"There are 20 seeds in all. 13 seeds are on the table. How many are hidden?","answer":7,"explain":"20 - 13 = 7 seeds are hidden."},{"kind":"numeric","prompt":"Nani Maa says 4. Which number makes 9 with 4?","answer":5,"explain":"4 + 5 = 9, so the answer is 5."},{"kind":"mcq","prompt":"Which pair of numbers makes 10?","options":["5 and 6","6 and 4","7 and 2","6 and 3"],"answer":1,"explain":"6 + 4 = 10."}]},{"id":"nm2","title":"Balushahi and Books","icon":"🍩","kind":"lesson","story":"Nandini and Chirag bring Nani Maa's favourite sweets and some books. Let us count them!","teach":[{"title":"Adding","body":"Nandini has 7 balushahi and Chirag has 5. Together, 7 + 5 = 12 balushahi.","visual":"🍩"},{"title":"Taking away","body":"7 - 5 = 2. This shows how many more one child has. It also shows how many are left.","visual":"📚"}],"questions":[{"kind":"numeric","prompt":"Nandini has 7 balushahi 🍩. Chirag has 5 balushahi. How many in all?","answer":12,"explain":"7 + 5 = 12 balushahi."},{"kind":"numeric","prompt":"Nandini has 7 balushahi. Chirag has 5. How many more does Nandini have?","answer":2,"explain":"7 - 5 = 2 more."},{"kind":"numeric","prompt":"Chirag got 9 story books 📚. Nandini got 7 puzzle books. How many books in all?","answer":16,"explain":"9 + 7 = 16 books."},{"kind":"numeric","prompt":"Use a tens frame. What is 18 - 9?","answer":9,"explain":"18 - 9 = 9."}]},{"id":"nm3","title":"Stamp Jumps","icon":"💌","kind":"lesson","story":"Nani Maa shows a jumping bead string called a ginladi. Jump along it to count the stamps!","teach":[{"title":"Jump to add","body":"15 stamps and 7 more. Jump +5 to reach 20, then +2 to reach 22. So 15 + 7 = 22.","visual":"🐸"},{"title":"Jump to subtract","body":"To do 52 - 37, jump back by 10s and 1s. You can also jump forward from 37 to 52. Both ways work.","visual":"↩️"}],"questions":[{"kind":"numeric","prompt":"They have 15 stamps. Nani Maa gives 7 more. How many stamps now? 💌","answer":22,"explain":"15 + 7 = 22 stamps."},{"kind":"numeric","prompt":"They have 22 stamps. Her brother gives 30 stamps. How many stamps now?","answer":52,"explain":"22 + 30 = 52 stamps."},{"kind":"numeric","prompt":"They have 52 stamps. 37 have famous faces. How many show monuments?","answer":15,"explain":"52 - 37 = 15 stamps."},{"kind":"numeric","prompt":"A frog is at 7. It jumps 10 forward, 3 times. Where does it land? 🐸","answer":37,"explain":"7, 17, 27, 37. It lands on 37."},{"kind":"mcq","prompt":"They have 52 stamps. They want 75. How many more stamps do they need?","options":["33","22","27","23"],"answer":3,"explain":"52 + 23 = 75, so they need 23 more."}]},{"id":"nm4","title":"The Number Grid Game","icon":"🎲","kind":"lesson","story":"Nandini and Chirag play a grid game with dice. The first to reach 91 or more wins!","teach":[{"title":"Move on the grid","body":"Going down a row on the grid is -10. Going up a row is +10. Moving one box side to side is +1 or -1.","visual":"🎲"},{"title":"Words for add and subtract","body":"Add words: more, total, sum. Subtract words: take away, difference, less.","visual":"📝"}],"questions":[{"kind":"numeric","prompt":"Nandini is at 23. She gets 11. She jumps +10, then +1. Where does she land?","answer":34,"explain":"23 + 10 = 33, then 33 + 1 = 34."},{"kind":"numeric","prompt":"Nandini is at 45. She gets 34. Where does she land? 🎲","answer":79,"explain":"45 + 30 = 75, then 75 + 4 = 79."},{"kind":"numeric","prompt":"Nandini is at 30. She gets 66. Where does she land?","answer":96,"explain":"30 + 66 = 96."},{"kind":"numeric","prompt":"Chirag is at 89. He gets 63 and moves back. Where does he land?","answer":26,"explain":"89 - 60 = 29, then 29 - 3 = 26."},{"kind":"mcq","prompt":"Which word means we should subtract?","options":["total","sum","more","difference"],"answer":3,"explain":"Difference tells us to subtract."}]},{"id":"nm5","title":"Magic Sums","icon":"🔮","kind":"lesson","story":"Nani Maa has solved a magic square in the newspaper. Can you find its secret too?","teach":[{"title":"The magic square","body":"In a magic square, every row, column and diagonal adds to the same number. This one uses 1 to 9 and the magic sum is 15.","visual":"🔮"},{"title":"Fill the missing number","body":"Add the numbers you know. Then find what is needed to reach the total. For 5 + 2 + ? = 15, the answer is 8.","visual":"🧩"}],"questions":[{"kind":"mcq","prompt":"Magic square rows: 2 7 6, 9 5 1, 4 3 8. What does each row add up to?","options":["15","16","18","14"],"answer":0,"explain":"2+7+6 = 15, 9+5+1 = 15, 4+3+8 = 15."},{"kind":"numeric","prompt":"In the magic square, the row is 9, 5, 1. Add them. What is the sum?","answer":15,"explain":"9 + 5 + 1 = 15."},{"kind":"numeric","prompt":"A row is 4, ?, 8. The magic sum is 15. What is the missing number?","answer":3,"explain":"4 + 8 = 12, and 12 + 3 = 15."},{"kind":"numeric","prompt":"Add the diagonal 2, 5, 8 of the magic square. What do you get?","answer":15,"explain":"2 + 5 + 8 = 15."}]},{"id":"nm6","title":"Fields and Orchard","icon":"🥕","kind":"lesson","story":"Nani Maa takes the children to her fields and orchard. There are radishes, carrots and many apples!","teach":[{"title":"Add with bundles","body":"25 red radishes and 36 white ones. Add the tens first (20 + 30), then the ones (5 + 6). 50 + 11 = 61.","visual":"🥬"},{"title":"Estimate first","body":"Make numbers easy to guess. 85 + 67 is about 90 + 70, so more than 100. Exact answer: 152.","visual":"🍎"}],"questions":[{"kind":"numeric","prompt":"Nani Maa plucked 25 red radishes and 36 white radishes. How many in all? 🥬","answer":61,"explain":"25 + 36 = 61 radishes."},{"kind":"numeric","prompt":"A box has 100 vegetables. 65 are tomatoes 🍅, the rest are carrots. How many carrots?","answer":35,"explain":"100 - 65 = 35 carrots."},{"kind":"numeric","prompt":"Nandini picked 85 apples and Chirag picked 67 apples. How many apples in all? 🍎","answer":152,"explain":"85 + 67 = 152 apples."},{"kind":"numeric","prompt":"Nandini has 85 apples. Chirag has 67. How many more does Nandini have?","answer":18,"explain":"85 - 67 = 18 more."},{"kind":"mcq","prompt":"Without adding exactly, is 150 - 49 more or less than 100?","options":["Less than 100","More than 100","Exactly 100"],"answer":1,"explain":"150 - 50 = 100, so 150 - 49 is a bit more."}]},{"id":"nm-boss","title":"Boss: The Sum Sprite","icon":"🧚","kind":"boss","boss":{"name":"Sum Sprite","taunt":"Can you solve my jumpy number puzzles?"},"story":"The Sum Sprite hides in Nani Maa's garden with tricky number puzzles. Use your jumps and tricks to win!","teach":[{"title":"Add, subtract, estimate","body":"Jump on a number line or use tens and ones. Estimate first, then find the exact answer.","visual":"🚂"}],"questions":[{"kind":"numeric","prompt":"Nani Maa hid some seeds. There are 20 in all. 8 are on the table. How many are hidden?","answer":12,"explain":"20 - 8 = 12 seeds are hidden."},{"kind":"numeric","prompt":"Rama sold 39 vadas on day one and 12 more on day two. How many vadas in all?","answer":51,"explain":"39 + 12 = 51 vadas."},{"kind":"numeric","prompt":"Gehu had 56 plants. Some dried up. 29 plants are left. How many dried up?","answer":27,"explain":"56 - 29 = 27 plants dried up."},{"kind":"numeric","prompt":"Babli didi sold 34 books on Monday and 45 on Tuesday. How many books in two days?","answer":79,"explain":"34 + 45 = 79 books."},{"kind":"numeric","prompt":"Team Red made 56 runs before lunch and 65 after lunch. How many runs in all?","answer":121,"explain":"56 + 65 = 121 runs."},{"kind":"mcq","prompt":"A magic square has the row 6, 1, 8. What is the magic sum?","options":["16","14","15","17"],"answer":2,"explain":"6 + 1 + 8 = 15."},{"kind":"mcq","prompt":"Is 20 + 41 more or less than 100?","options":["More than 100","Less than 100","Exactly 100"],"answer":1,"explain":"20 + 41 = 61, which is less than 100."}]}]},{"id":"funshapes3","index":4,"name":"Fun with Shapes","subtitle":"Squares, rectangles, triangles and circles","emoji":"🔷","palette":{"from":"#34d399","to":"#065f46"},"lessons":[{"id":"fs1","title":"Amma's Rangoli","icon":"🎨","kind":"lesson","story":"Amma made a pretty rangoli with dots and shapes. Help us find the lines in it!","teach":[{"title":"Straight and curved lines","body":"A straight line does not bend. A curved line bends like a rainbow.","visual":"🌈"},{"title":"Shapes in a rangoli","body":"A rangoli can have circles, triangles and squares. Count them to see how many.","visual":"🪔"}],"questions":[{"kind":"mcq","prompt":"Which shape is made with a curved line?","options":["Circle ⭕","Square 🟦","Rectangle ▭","Triangle 🔺"],"answer":0,"explain":"A circle is round, so it is made with a curved line."},{"kind":"mcq","prompt":"Which shape is made with straight lines?","options":["Circle ⭕","Bottle cap 🔘","Bangle 💍","Triangle 🔺"],"answer":3,"explain":"A triangle has straight sides. The others are round."},{"kind":"numeric","prompt":"Amma's rangoli has ⭕⭕ 🔺🔺🔺 🟦🟦🟦🟦. How many shapes use straight lines?","answer":7,"explain":"Triangles and squares use straight lines. 3 + 4 = 7."},{"kind":"numeric","prompt":"Look at ⭕⭕ 🔺🔺🔺 🟦🟦🟦🟦. How many shapes use curved lines?","answer":2,"explain":"Only the 2 circles use curved lines."}]},{"id":"fs2","title":"Rectangles and Boxes","icon":"📦","kind":"lesson","story":"Murugan opens a matchbox for his Diwali gift. What shapes are on its faces?","teach":[{"title":"The rectangle","body":"A rectangle has 4 sides and 4 corners. Its opposite sides are equal in length.","visual":"🚪"},{"title":"Faces of a box","body":"Trace the faces of a matchbox to get rectangles. A cuboid has rectangle or square faces.","visual":"📦"}],"questions":[{"kind":"numeric","prompt":"How many sides does a rectangle have?","answer":4,"explain":"A rectangle has 4 sides."},{"kind":"numeric","prompt":"A door is a rectangle. Its long side is 6 feet. How long is the opposite long side?","answer":6,"explain":"Opposite sides of a rectangle are equal, so it is also 6 feet."},{"kind":"mcq","prompt":"Which object has rectangular faces?","options":["A matchbox","A ball ⚽","A bottle cap 🔘","A bangle 💍"],"answer":0,"explain":"A matchbox is a cuboid, so its faces are rectangles."},{"kind":"mcq","prompt":"Can a cuboid have a face shaped like a triangle?","options":["Only a big cuboid","Only a small cuboid","No","Yes"],"answer":2,"explain":"The faces of a cuboid are rectangles or squares, never triangles."}]},{"id":"fs3","title":"Same to Same: Squares","icon":"♟️","kind":"lesson","story":"Rani got a board game from her aunt. Its board is a square. Let us look at it!","teach":[{"title":"The square","body":"A square has 4 sides and 4 corners. All 4 sides are equal in length.","visual":"🟦"},{"title":"Square or rectangle?","body":"In a rectangle, only the opposite sides must be equal. In a square, all sides must be equal.","visual":"♟️"}],"questions":[{"kind":"mcq","prompt":"Chess boards and ludo boards have which shape?","options":["Square","Triangle","Circle","Oval"],"answer":0,"explain":"Chess and ludo boards are square in shape."},{"kind":"numeric","prompt":"One side of a square tile is 5 cm. How long is each of the other sides?","answer":5,"explain":"All sides of a square are equal, so each side is 5 cm."},{"kind":"numeric","prompt":"It takes 4 matchsticks to make 1 square. How many matchsticks make 3 separate squares?","answer":12,"explain":"4 + 4 + 4 = 12 matchsticks."},{"kind":"mcq","prompt":"A rectangle has sides 4 cm and 2 cm. Is it a square?","options":["Yes, it is a box","Yes, it has 4 corners","Yes, it has 4 sides","No, all sides are not equal"],"answer":3,"explain":"A square needs all sides equal. 4 cm and 2 cm are not equal."}]},{"id":"fs4","title":"Square Corners","icon":"📐","kind":"lesson","story":"Lina wants a tile that fits the corner of a table. Which corner will it fit?","teach":[{"title":"Square corner","body":"The corner of a book or a table is a square corner. Squares and rectangles have only square corners.","visual":"📖"},{"title":"Less or more","body":"Two paper strips can make a corner. It can be less than, the same as, or more than a square corner.","visual":"📐"}],"questions":[{"kind":"numeric","prompt":"How many square corners does a rectangle have?","answer":4,"explain":"A rectangle has 4 corners and all of them are square corners."},{"kind":"mcq","prompt":"Which one has a square corner?","options":["The edge of a bangle 💍","A rainbow 🌈","The top of a ball ⚽","The corner of a book 📖"],"answer":3,"explain":"The corner of a book is a square corner."},{"kind":"mcq","prompt":"A corner is smaller than a square corner. We say it is:","options":["A curved corner","A square corner","Less than a square corner","More than a square corner"],"answer":2,"explain":"Smaller than a square corner means less than a square corner."},{"kind":"numeric","prompt":"A square has 4 square corners. A rectangle also has 4. How many in both together?","answer":8,"explain":"4 + 4 = 8 square corners."}]},{"id":"fs5","title":"So Many Triangles","icon":"🔺","kind":"lesson","story":"Triangles are hiding in the rangoli, the roof and the flag. Can you spot them?","teach":[{"title":"The triangle","body":"A triangle has 3 sides and 3 corners. Its sides are straight.","visual":"🔺"},{"title":"Triangles around us","body":"Look at a roof, a flag and a rangoli. Some faces are triangles.","visual":"🚩"}],"questions":[{"kind":"numeric","prompt":"How many sides does a triangle have?","answer":3,"explain":"A triangle has 3 sides."},{"kind":"mcq","prompt":"Which shape has 3 corners?","options":["Circle ⭕","Square 🟦","Rectangle ▭","Triangle 🔺"],"answer":3,"explain":"A triangle has 3 corners."},{"kind":"numeric","prompt":"How many corners are there in 2 triangles 🔺🔺?","answer":6,"explain":"3 + 3 = 6 corners."},{"kind":"numeric","prompt":"Lina made 3 rows of triangles. Each row has 4 triangles 🔺🔺🔺🔺. How many triangles in all?","answer":12,"explain":"4 + 4 + 4 = 12 triangles."}]},{"id":"fs6","title":"Circus with Circles","icon":"🎪","kind":"lesson","story":"Welcome to the circus! Everything here is round. Let us meet the circle.","teach":[{"title":"The circle","body":"A circle is round and has one curved line. It has no corners and no straight sides.","visual":"⭕"},{"title":"Fold a paper plate","body":"Fold a plate in half to get a straight line. Fold it again. The lines meet at the centre.","visual":"🍽️"}],"questions":[{"kind":"mcq","prompt":"Which object is like a circle?","options":["A bangle 💍","A door 🚪","A matchbox","A book 📖"],"answer":0,"explain":"A bangle is round like a circle."},{"kind":"numeric","prompt":"How many corners does a circle have?","answer":0,"explain":"A circle is round, so it has no corners."},{"kind":"numeric","prompt":"Rani folds a paper plate in half 2 times, in different ways. How many fold lines does she see?","answer":2,"explain":"Each fold makes one straight line, so 2 folds make 2 lines."},{"kind":"mcq","prompt":"The fold lines of a paper plate meet at a point. What is that point called?","options":["A face","A corner","The centre of the circle","A side"],"answer":2,"explain":"The point where the lines meet is the centre of the circle."}]},{"id":"fs-boss","title":"The Shape Giant","icon":"👑","kind":"boss","boss":{"name":"Shape Giant","taunt":"Ha! Can you name all my shapes?"},"story":"The Shape Giant is hiding the rangoli shapes! Answer his questions to win them back.","teach":[{"title":"Shapes review","body":"Circle: curved, 0 corners. Triangle: 3 sides. Rectangle and square: 4 sides, 4 square corners.","visual":"🔷"}],"questions":[{"kind":"mcq","prompt":"Which shape has no corners?","options":["Circle ⭕","Square 🟦","Rectangle ▭","Triangle 🔺"],"answer":0,"explain":"A circle is round and has no corners."},{"kind":"numeric","prompt":"How many sides does a square have?","answer":4,"explain":"A square has 4 sides, all equal."},{"kind":"numeric","prompt":"A rectangle has a long side of 8 cm. How long is the opposite long side?","answer":8,"explain":"Opposite sides of a rectangle are equal."},{"kind":"numeric","prompt":"Amma's rangoli has ⭕⭕ 🔺🔺🔺 🟦🟦🟦🟦. How many shapes are there in all?","answer":9,"explain":"2 + 3 + 4 = 9 shapes."},{"kind":"numeric","prompt":"How many matchsticks do you need to make 2 separate squares?","answer":8,"explain":"4 + 4 = 8 matchsticks."},{"kind":"mcq","prompt":"Which one has a square corner?","options":["A rainbow 🌈","A ball ⚽","A bangle 💍","The corner of a table"],"answer":3,"explain":"The corner of a table is a square corner."},{"kind":"mcq","prompt":"Which shape is made with only a curved line?","options":["Square 🟦","Rectangle ▭","Circle ⭕","Triangle 🔺"],"answer":2,"explain":"Only a circle is made with a curved line."}]}]},{"id":"hundredsone3","index":5,"name":"House of Hundreds - I","subtitle":"3-digit numbers up to 500","emoji":"🏠","palette":{"from":"#4ade80","to":"#14532d"},"lessons":[{"id":"ha1","title":"Counting Past 200","icon":"📿","kind":"lesson","story":"Teji and Jojo reach the mela. There are so many bangles to count. Let us count in tens!","teach":[{"title":"Count in tens","body":"Count 10, 20, 30 and go on to 100, 110, 120 and 200. Tens make big counting easy.","visual":"🔟"},{"title":"Past 200","body":"200 and 80 more is 280. 298 and 1 more is 299, and 299 and 1 more is 300.","visual":"📿"}],"questions":[{"kind":"numeric","prompt":"Teji counts bangles in tens: 250, 260, 270, ... What number comes next?","answer":280,"explain":"270 and 10 more is 280."},{"kind":"mcq","prompt":"A toran has 200 triangles. Then 50 more are added. How many triangles are there?","options":["250","300","205","150"],"answer":0,"explain":"200 and 50 more is 250."},{"kind":"numeric","prompt":"Jojo has 298 toffees and gets 1 more. How many toffees does he have now?","answer":299,"explain":"298 and 1 more is 299."},{"kind":"numeric","prompt":"Teji counted 280 bangles. How many more bangles make 300?","answer":20,"explain":"280 and 20 more make 300."}]},{"id":"ha2","title":"Hundreds, Tens and Ones","icon":"📦","kind":"lesson","story":"Arvind Dada packs sweets in boxes. Help him count the boxes and the loose sweets!","teach":[{"title":"H, T and O","body":"A box of 100 sweets is H. A box of 10 is T. Loose sweets are O, the ones.","visual":"📦"},{"title":"Write it in parts","body":"235 is 2 H, 3 T and 5 O. We can write it as 200 + 35.","visual":"🧱"}],"questions":[{"kind":"mcq","prompt":"Dada has 3 boxes of 100, 4 boxes of 10 and 2 loose sweets 🍬. How many sweets in all?","options":["324","342","432","234"],"answer":1,"explain":"3 hundreds, 4 tens and 2 ones make 342."},{"kind":"numeric","prompt":"How many boxes of 10 fit in one box of 100?","answer":10,"explain":"10 tens make 1 hundred."},{"kind":"numeric","prompt":"Dada opens 4 boxes of 100. How many boxes of 10 will he find?","answer":40,"explain":"Each box of 100 has 10 tens, so 4 boxes have 40 tens."},{"kind":"numeric","prompt":"Teji's number is 15 less than 250. What is 250 − 15?","answer":235,"explain":"250 take away 15 is 235."}]},{"id":"ha3","title":"Number Line Hops","icon":"📏","kind":"lesson","story":"Jojo hops along the tiled path in the mela. Fill in the missing numbers!","teach":[{"title":"Numbers in order","body":"Numbers sit in order on a number line. 235 lies between 200 and 250.","visual":"📏"},{"title":"One more, ten more","body":"One more changes the ones digit. Ten more changes the tens digit. 147 and 10 more is 157.","visual":"🎚️"}],"questions":[{"kind":"numeric","prompt":"Jojo hops on tiles 211, 212, ?, 214. Which number is on the empty tile?","answer":213,"explain":"The number between 212 and 214 is 213."},{"kind":"numeric","prompt":"On a number line, how far is 387 from 400?","answer":13,"explain":"387 + 13 = 400, so it is 13 away."},{"kind":"numeric","prompt":"Teji's slider shows 147. Slide it up by ten. What does it show now?","answer":157,"explain":"Ten more than 147 is 157."},{"kind":"numeric","prompt":"The slider shows 289. Slide it down by ten. What does it show now?","answer":279,"explain":"Ten less than 289 is 279."}]},{"id":"ha4","title":"Hop Hundreds Home","icon":"🏢","kind":"lesson","story":"Teji and Jojo see a big apartment. Every home has a house number. Find the right one!","teach":[{"title":"Right and up","body":"One house to the right is 1 more. One floor up is 10 more.","visual":"🏢"},{"title":"Left and down","body":"One house to the left is 1 less. One floor down is 10 less.","visual":"🏠"}],"questions":[{"kind":"numeric","prompt":"Which house is one floor above house 238?","answer":248,"explain":"One floor up is 10 more, and 238 + 10 = 248."},{"kind":"numeric","prompt":"Teji lives at house 212. Jojo lives one house to the right. What is Jojo's house number?","answer":213,"explain":"One house to the right is 1 more, so 213."},{"kind":"numeric","prompt":"Which house is one floor below house 113?","answer":103,"explain":"One floor down is 10 less, and 113 − 10 = 103."},{"kind":"mcq","prompt":"Arvind Dada is at house 258. He goes one house to the left. Where is he now?","options":["248","259","268","257"],"answer":3,"explain":"One house to the left is 1 less, so 257."}]},{"id":"ha5","title":"Bigger or Smaller?","icon":"⚖️","kind":"lesson","story":"Farooq Chacha has trays of laddoos 🟠. Which tray has more? Let us compare!","teach":[{"title":"Hundreds first","body":"More hundreds means a bigger number. 321 > 231 because 3 hundreds beat 2 hundreds.","visual":"⚖️"},{"title":"Then tens and ones","body":"If hundreds are the same, look at tens. 209 < 290 because 0 tens is less than 9 tens.","visual":"🔍"}],"questions":[{"kind":"mcq","prompt":"Chacha has 487 laddoos in one shop and 423 in another. Which sign fits? 487 __ 423","options":[">","<","="],"answer":0,"explain":"487 has more tens than 423, so 487 > 423."},{"kind":"mcq","prompt":"Which number is smaller, 209 or 290?","options":["209","290"],"answer":0,"explain":"Both have 2 hundreds, but 0 tens is less than 9 tens."},{"kind":"mcq","prompt":"Which number is greater, 393 or 400?","options":["393","400"],"answer":1,"explain":"400 has 4 hundreds and 393 has only 3 hundreds."},{"kind":"mcq","prompt":"Which sign fits? 199 __ 201","options":["<","=",">"],"answer":0,"explain":"199 has 1 hundred and 201 has 2 hundreds, so 199 < 201."}]},{"id":"ha6","title":"Order and Riddles","icon":"🧩","kind":"lesson","story":"Time for number riddles at the mela! Put numbers in order and find the secret ones.","teach":[{"title":"Smallest to greatest","body":"Compare hundreds, then tens, then ones. A 2-digit number like 99 is smaller than any 3-digit number.","visual":"🔢"}],"questions":[{"kind":"mcq","prompt":"Which is the smallest number? 374, 473, 347, 437","options":["437","374","473","347"],"answer":3,"explain":"Start with hundreds. 347 and 374 have 3, and 347 has fewer tens."},{"kind":"mcq","prompt":"Which is the greatest number? 466, 437, 439, 447, 483","options":["483","439","447","466"],"answer":0,"explain":"483 has the most tens among the 4 hundreds."},{"kind":"mcq","prompt":"Arrange from smallest to biggest: 456, 389, 207, 99, 110","options":["110, 99, 207, 389, 456","99, 110, 389, 207, 456","456, 389, 207, 110, 99","99, 110, 207, 389, 456"],"answer":3,"explain":"99 is smallest, then 110, 207, 389 and 456."},{"kind":"mcq","prompt":"I have the digits 9, 1 and 5. I am less than 200. I have 9 ones. Who am I?","options":["591","519","195","159"],"answer":3,"explain":"Less than 200 means 1 hundred, and 9 ones gives 159."}]},{"id":"ha-boss","title":"King of the Hundreds","icon":"👑","kind":"boss","boss":{"name":"King Kilo","taunt":"Can you beat my big numbers?"},"story":"King Kilo guards the House of Hundreds. Use all your number skills to open the door!","teach":[{"title":"Review","body":"Count in tens, use H, T and O, hop on the number line and compare hundreds first.","visual":"🏠"}],"questions":[{"kind":"numeric","prompt":"Count in tens: 270, 280, 290, ... What comes next?","answer":300,"explain":"290 and 10 more is 300."},{"kind":"mcq","prompt":"Dada has 2 boxes of 100, 5 boxes of 10 and 6 loose sweets 🍬. How many sweets?","options":["562","265","256","526"],"answer":2,"explain":"2 hundreds, 5 tens and 6 ones make 256."},{"kind":"numeric","prompt":"Teji's slider shows 367. Slide it down by 2. What does it show?","answer":365,"explain":"367 take away 2 is 365."},{"kind":"numeric","prompt":"Which house is one floor above house 327?","answer":337,"explain":"One floor up is 10 more, and 327 + 10 = 337."},{"kind":"mcq","prompt":"Which is greater, 321 or 231?","options":["321","231"],"answer":0,"explain":"3 hundreds beat 2 hundreds."},{"kind":"mcq","prompt":"I am more than 300 and less than 400. I have no tens. My ones and hundreds are the same. Who am I?","options":["303","313","333","330"],"answer":0,"explain":"No tens means a 0 in the middle, so 303."},{"kind":"numeric","prompt":"The jumps go 100, 200, 300. What hundred comes next?","answer":400,"explain":"After 300 comes 400."}]}]},{"id":"rakshabandhan3","index":6,"name":"Raksha Bandhan","subtitle":"Multiplication and division","emoji":"🎀","palette":{"from":"#a78bfa","to":"#4c1d95"},"lessons":[{"id":"rb1","title":"Let's Make Rakhis","icon":"🧵","kind":"lesson","story":"Raksha Bandhan is tomorrow! Dhara and Gopal are making Rakhis, and each Rakhi needs the same things.","teach":[{"title":"Equal groups","body":"Each Rakhi uses 2 threads. For 5 Rakhis we add 2 + 2 + 2 + 2 + 2 = 10 threads.","visual":"🧵"},{"title":"Times means groups","body":"5 groups of 2 is called 5 times 2. We write 5 × 2 = 10. It is repeated addition.","visual":"✖️"}],"questions":[{"kind":"numeric","prompt":"Each Rakhi has 4 beads. How many beads do 5 Rakhis need? 🔴🔴🔴🔴 each Rakhi","answer":20,"explain":"4 + 4 + 4 + 4 + 4 = 20, so 5 × 4 = 20."},{"kind":"numeric","prompt":"Each Rakhi needs 1 flower 🌸. How many flowers do 5 Rakhis need?","answer":5,"explain":"5 × 1 = 5 flowers."},{"kind":"mcq","prompt":"Which is the same as 4 + 4 + 4?","options":["3 × 3","4 × 4","4 + 3","3 × 4"],"answer":3,"explain":"There are 3 groups of 4, so it is 3 × 4."},{"kind":"numeric","prompt":"Each Rakhi uses 2 threads 🧵. How many threads for 10 Rakhis?","answer":20,"explain":"10 groups of 2 make 20 threads."}]},{"id":"rb2","title":"Laddoos in Boxes","icon":"🍬","kind":"lesson","story":"Gopal and Dhara go to the Jagannath Sweet Shop to buy laddoos for Atya.","teach":[{"title":"Count in groups","body":"One box has 3 + 3 + 3 = 9 laddoos. That is 3 × 3 = 9.","visual":"🍬"},{"title":"Same total, different groups","body":"2 boxes of 9 laddoos is 2 × 9 = 18. Six groups of 3 also make 18, so 6 × 3 = 18.","visual":"📦"}],"questions":[{"kind":"numeric","prompt":"One box has 9 laddoos. Dhara buys 2 boxes. How many laddoos is that?","answer":18,"explain":"9 + 9 = 18, so 2 × 9 = 18."},{"kind":"mcq","prompt":"What is 6 × 3?","options":["9","15","18","12"],"answer":2,"explain":"3 + 3 + 3 + 3 + 3 + 3 = 18."},{"kind":"numeric","prompt":"Dhara counts the plants in a flower bed: 6 + 6 + 6 + 6 + 6 + 6 + 6 + 6 = ?","answer":48,"explain":"8 groups of 6 make 48."},{"kind":"mcq","prompt":"Gopal says 6 × 8 and Dhara says 8 × 6. Who is right?","options":["Both are right, the answer is 48","Only Dhara is right","Only Gopal is right","Both are wrong"],"answer":0,"explain":"Changing the order gives the same answer: 6 × 8 = 8 × 6 = 48."}]},{"id":"rb3","title":"Sharing Equally","icon":"🍰","kind":"lesson","story":"Nine people will be at home. Dhara must share the sweets so that everyone gets the same.","teach":[{"title":"Equal sharing","body":"18 laddoos shared by 9 people gives 2 each. We write 18 ÷ 9 = 2.","visual":"🍬"},{"title":"Take away again and again","body":"Share 20 kaju katlis among 5 people. 20 − 5 − 5 − 5 − 5 = 0, so each gets 4 and 20 ÷ 5 = 4.","visual":"➖"}],"questions":[{"kind":"numeric","prompt":"Share 16 kaju katlis equally among 4 people. How many does each person get?","answer":4,"explain":"16 ÷ 4 = 4, because 4 + 4 + 4 + 4 = 16."},{"kind":"numeric","prompt":"Share 15 pedas equally among 5 people. How many does each get?","answer":3,"explain":"15 ÷ 5 = 3."},{"kind":"numeric","prompt":"Each cycle needs 2 wheels 🚲. How many cycles can we fit with 12 wheels?","answer":6,"explain":"12 ÷ 2 = 6 cycles."},{"kind":"mcq","prompt":"What is 20 ÷ 5?","options":["15","4","5","25"],"answer":1,"explain":"20 − 5 − 5 − 5 − 5 = 0, that is 4 times, so 20 ÷ 5 = 4."}]},{"id":"rb4","title":"Skip Jumping Game","icon":"🦘","kind":"lesson","story":"In the evening, Atya draws a number track on the ground. Dhara skip jumps from 0!","teach":[{"title":"Skip jumping by 3","body":"Dhara jumps 0, 3, 6, 9, 12. Each jump adds 3. After 3 jumps she is on 9, so 3 × 3 = 9.","visual":"🦘"},{"title":"Jumps make tables","body":"Jumping by 4 gives 4, 8, 12, 16, 20. These numbers are the times-4 table.","visual":"📈"}],"questions":[{"kind":"numeric","prompt":"Dhara jumps by 3: 3, 6, 9, ... Which number comes next?","answer":12,"explain":"9 + 3 = 12."},{"kind":"numeric","prompt":"Dhara starts at 0 and jumps by 3. Where is she after 6 jumps?","answer":18,"explain":"6 × 3 = 18."},{"kind":"numeric","prompt":"Gopal jumps by 4 from 0. Where does he land after 5 jumps?","answer":20,"explain":"4, 8, 12, 16, 20. So 5 × 4 = 20."},{"kind":"mcq","prompt":"Gopal writes 32, 40, 48, 56. How big is each jump?","options":["10","8","6","4"],"answer":1,"explain":"40 − 32 = 8, and each jump adds 8."}]},{"id":"rb5","title":"Table Patterns","icon":"🔍","kind":"lesson","story":"Mithu makes tables with sticks. Gopal notices patterns in the times-5 table!","teach":[{"title":"Times-5 pattern","body":"The times-5 table goes 5, 10, 15, 20, 25, 30. Every answer ends in 5 or 0.","visual":"🖐️"},{"title":"Tables add up","body":"4 × 2 = 8 and 4 × 3 = 12. Add them: 8 + 12 = 20, which is 4 × 5. So times-2 plus times-3 is times-5.","visual":"➕"}],"questions":[{"kind":"numeric","prompt":"What is 7 × 5?","answer":35,"explain":"5, 10, 15, 20, 25, 30, 35. So 7 × 5 = 35."},{"kind":"mcq","prompt":"Which answer ends in 5?","options":["6 × 5","9 × 5","8 × 5","10 × 5"],"answer":1,"explain":"9 × 5 = 45 ends in 5. The others are 40, 50 and 30."},{"kind":"mcq","prompt":"Without solving, what is the last digit of 12 × 5? (12 × 5 = 60)","options":["0","6","5","2"],"answer":0,"explain":"Every even number times 5 ends in 0."},{"kind":"numeric","prompt":"3 × 2 = 6 and 3 × 3 = 9. Add 6 + 9. What do you get? (It equals 3 × 5.)","answer":15,"explain":"6 + 9 = 15, and 3 × 5 = 15 too."}]},{"id":"rb6","title":"Wheels for the Rath","icon":"🛞","kind":"lesson","story":"Gopal is making a cardboard rath! Each wheel needs 5 spokes, and he needs many wheels.","teach":[{"title":"Use 10 first","body":"10 wheels with 5 spokes each need 10 × 5 = 50 spokes. Another 10 wheels need 50 more, so 20 wheels need 100.","visual":"🛞"},{"title":"Break big numbers","body":"30 × 5 means 10 × 5 three times: 50 + 50 + 50 = 150 spokes.","visual":"🧩"}],"questions":[{"kind":"numeric","prompt":"Each wheel needs 5 spokes. How many spokes do 20 wheels need?","answer":100,"explain":"10 wheels need 50 spokes, so 20 wheels need 50 + 50 = 100."},{"kind":"numeric","prompt":"What is 30 × 5?","answer":150,"explain":"50 + 50 + 50 = 150."},{"kind":"numeric","prompt":"A spider 🕷️ has 8 legs. How many legs do 15 spiders have? (10 spiders have 80 legs.)","answer":120,"explain":"10 spiders have 80 legs and 5 spiders have 40 legs. 80 + 40 = 120."},{"kind":"numeric","prompt":"An auto rickshaw has 3 wheels. How many wheels do 18 auto rickshaws have?","answer":54,"explain":"10 autos have 30 wheels and 8 autos have 24 wheels. 30 + 24 = 54."}]},{"id":"rb7","title":"Puri Beach Shopping","icon":"🐚","kind":"lesson","story":"At Puri Beach, Dhruv collects 112 sea-shells to make necklaces for his friends.","teach":[{"title":"Money and groups","body":"One wall-hanging costs ₹42. Two cost 42 + 42 = ₹84, which is 2 × 42.","visual":"💰"},{"title":"Subtract again and again","body":"Dhruv uses 28 shells for each necklace. 112 − 28 = 84, then 84 − 28 = 56. Count how many times you can take away 28.","visual":"🐚"}],"questions":[{"kind":"numeric","prompt":"One wall-hanging costs ₹42. How many rupees do two wall-hangings cost?","answer":84,"explain":"42 + 42 = 84 rupees."},{"kind":"numeric","prompt":"One rabdi cup costs ₹75. How many rupees do 2 cups cost?","answer":150,"explain":"75 + 75 = 150 rupees."},{"kind":"numeric","prompt":"Dhruv has 112 shells. Each necklace uses 28 shells. How many necklaces can he make?","answer":4,"explain":"112 − 28 = 84, 84 − 28 = 56, 56 − 28 = 28, 28 − 28 = 0. That is 4 necklaces."},{"kind":"numeric","prompt":"Preeti changes a ₹500 note into ₹100 notes. How many notes does she get?","answer":5,"explain":"100 + 100 + 100 + 100 + 100 = 500, so she gets 5 notes."}]},{"id":"rb-boss","title":"Rakhi Thread Dragon","icon":"🐉","kind":"boss","boss":{"name":"Tangle the Thread Dragon","taunt":"Can you multiply and share like Dhara and Gopal?"},"story":"A thread dragon is tangling all the Rakhis! Use groups, sharing and skip jumps to free them.","teach":[{"title":"Remember","body":"Times means equal groups added again and again. Division means sharing equally or taking away again and again.","visual":"🎀"}],"questions":[{"kind":"numeric","prompt":"Each Rakhi uses 4 beads. How many beads do 6 Rakhis need?","answer":24,"explain":"6 × 4 = 24 beads."},{"kind":"numeric","prompt":"There are 9 people at home and each gets 4 jalebis. How many jalebis do they need?","answer":36,"explain":"9 × 4 = 36 jalebis."},{"kind":"numeric","prompt":"Share 32 legs equally among spiders with 8 legs each. How many spiders are there?","answer":4,"explain":"32 ÷ 8 = 4 spiders."},{"kind":"mcq","prompt":"A frog jumps by 7 from 0: 7, 14, 21, ... Where does it land next?","options":["35","24","27","28"],"answer":3,"explain":"21 + 7 = 28."},{"kind":"mcq","prompt":"Without solving, what is the last digit of 14 × 5? (14 × 5 = 70)","options":["0","4","7","5"],"answer":0,"explain":"Even numbers times 5 always end in 0."},{"kind":"numeric","prompt":"Gopal needs 5 spokes for each wheel. How many spokes do 40 wheels need?","answer":200,"explain":"10 wheels need 50 spokes, so 40 wheels need 4 × 50 = 200."},{"kind":"numeric","prompt":"Share 24 kaju katlis equally among 6 children. How many does each child get?","answer":4,"explain":"24 ÷ 6 = 4, because 6 × 4 = 24."}]}]},{"id":"fairshare3","index":7,"name":"Fair Share","subtitle":"Halves, quarters and double","emoji":"🫓","palette":{"from":"#22d3ee","to":"#164e63"},"lessons":[{"id":"fsh1","title":"Fair Shares","icon":"🫓","kind":"lesson","story":"Shabnam and Mukta sit down for lunch. They have a paratha and a chocolate to share.","teach":[{"title":"Equal means fair","body":"In a fair share, every part is the same size. Equal parts are fair parts.","visual":"⚖️"},{"title":"Fold to check","body":"Fold a piece over itself. If both sides match exactly, the parts are equal.","visual":"🫓"}],"questions":[{"kind":"mcq","prompt":"Shabnam gives Mukta a bigger part and keeps a small part. Is this a fair share?","options":["Nobody can tell","Yes, it is fair","No, the parts are not equal","Yes, bigger is always better"],"answer":2,"explain":"A fair share needs equal parts, and these parts are not the same size."},{"kind":"mcq","prompt":"Why does Shabnam fold the paratha over itself?","options":["To check if both parts match and are equal","To make the paratha hot","To make the paratha bigger","To hide it from Mukta"],"answer":0,"explain":"If the two sides match exactly, the parts are equal."},{"kind":"numeric","prompt":"Mukta and Shabnam share 8 chocolate pieces equally. 🍫🍫🍫🍫🍫🍫🍫🍫 How many pieces does each girl get?","answer":4,"explain":"8 shared equally between 2 girls is 4 each."},{"kind":"numeric","prompt":"10 chikki pieces are shared equally between two friends. How many pieces does each friend get?","answer":5,"explain":"10 shared equally between 2 friends is 5 each."}]},{"id":"fsh2","title":"Halves","icon":"🌗","kind":"lesson","story":"Shabnam folds the paratha and cuts it into two equal parts. What do we call each part?","teach":[{"title":"One half","body":"When 1 whole is shared equally between 2 people, each share is called a half.","visual":"🌗"},{"title":"Two halves","body":"Two halves put together make one whole. Say one half, not 1 out of 2.","visual":"🫓"}],"questions":[{"kind":"mcq","prompt":"A paratha is cut into 2 equal parts. What is each part called?","options":["Double","Two wholes","One half","A quarter"],"answer":2,"explain":"Two equal parts of a whole are called halves."},{"kind":"numeric","prompt":"How many halves make one whole?","answer":2,"explain":"Half and half together make one whole, so 2 halves."},{"kind":"numeric","prompt":"Here are 8 mangoes. 🥭🥭🥭🥭🥭🥭🥭🥭 Share them equally between two children. How many mangoes does each child get?","answer":4,"explain":"Each child gets half of 8, and half of 8 is 4."},{"kind":"mcq","prompt":"You fold a square paper in half. Can you fold it in more than one way?","options":["Yes, along the middle or corner to corner","No, a square cannot be folded","No, there is only one way","Only when it is a rectangle"],"answer":0,"explain":"Folding down the middle or across the corners both give two equal halves."}]},{"id":"fsh3","title":"Half and Double","icon":"🔮","kind":"lesson","story":"Shabnam and Mukta play a marble game. They count who got half and who got double.","teach":[{"title":"Half and double","body":"3 is half of 6. 6 is double of 3. Double means two times.","visual":"🔮"},{"title":"Switch it around","body":"If one is half of the other, the other is double of the first.","visual":"🔄"}],"questions":[{"kind":"mcq","prompt":"4 marbles are ______ of 8 marbles. 🔮 Pick the right word.","options":["the same","a quarter","double","half"],"answer":3,"explain":"4 is half of 8 because 4 and 4 make 8."},{"kind":"mcq","prompt":"12 marbles are ______ of 6 marbles. 🔮 Pick the right word.","options":["half","the same","a quarter","double"],"answer":3,"explain":"12 is two times 6, so it is double."},{"kind":"numeric","prompt":"What is double of 7?","answer":14,"explain":"Double of 7 is 7 + 7, which is 14."},{"kind":"numeric","prompt":"Shabnam has 16 marbles. Mukta has half as many. How many marbles does Mukta have?","answer":8,"explain":"Half of 16 is 8 because 8 + 8 = 16."}]},{"id":"fsh4","title":"Quarters","icon":"🍰","kind":"lesson","story":"Four friends want to share one chikki. Each friend must get a fair part.","teach":[{"title":"One quarter","body":"When a whole is shared equally among 4 people, each share is called a quarter.","visual":"🍰"},{"title":"4 quarters","body":"4 quarters make one whole. Half of a half is a quarter.","visual":"🍪"}],"questions":[{"kind":"numeric","prompt":"How many quarters are there in one whole?","answer":4,"explain":"A whole is shared into 4 equal quarters."},{"kind":"mcq","prompt":"One chikki is shared equally among 4 friends. What part does each friend get?","options":["One whole","One half","One quarter","Double"],"answer":2,"explain":"Sharing a whole equally among 4 gives a quarter each."},{"kind":"mcq","prompt":"Which part is half of a half?","options":["A whole","Double","A quarter","Three halves"],"answer":2,"explain":"Cut a half into 2 equal parts, and each part is a quarter."},{"kind":"numeric","prompt":"12 laddoos 🟠 are shared equally among 4 children. How many laddoos does each child get?","answer":3,"explain":"Each child gets a quarter, and 12 shared among 4 is 3."}]},{"id":"fsh5","title":"Quarters and Whole","icon":"🧩","kind":"lesson","story":"Lakshanya and Peehu have 16 flowers each. They tie them into bunches.","teach":[{"title":"Count the quarters","body":"1 quarter, 2 quarters, 3 quarters, 4 quarters. 2 quarters make a half.","visual":"🧩"},{"title":"Four make a whole","body":"4 quarters make the complete whole. 3 quarters is one quarter less than a whole.","visual":"🌸"}],"questions":[{"kind":"mcq","prompt":"2 quarters of a paratha are the same as what?","options":["One half","Three quarters","One whole","One quarter"],"answer":0,"explain":"2 quarters together make one half."},{"kind":"numeric","prompt":"A paratha is cut into 4 equal parts. Mukta eats 1 quarter. How many quarters are left?","answer":3,"explain":"4 quarters take away 1 quarter leaves 3 quarters."},{"kind":"numeric","prompt":"Peehu has 16 flowers 🌸 and ties a quarter of them. How many flowers does she tie?","answer":4,"explain":"A quarter of 16 is 4 because 4 + 4 + 4 + 4 = 16."},{"kind":"mcq","prompt":"Lakshanya ties half of her 16 flowers, which is 8. Peehu ties 4. Lakshanya tied ______ the flowers Peehu tied.","options":["a quarter of","the same as","half","double"],"answer":3,"explain":"8 is two times 4, so Lakshanya tied double."}]},{"id":"fsh-boss","title":"Fair Share Champion","icon":"🏆","kind":"boss","boss":{"name":"Greedy Gobbler","taunt":"I will take the biggest piece of everything!"},"story":"The Greedy Gobbler wants a bigger share of the lunch. Show him what fair really means!","teach":[{"title":"Fair share review","body":"Fair parts are equal. 2 halves make a whole. 4 quarters make a whole. Double is two times.","visual":"🫓"}],"questions":[{"kind":"mcq","prompt":"Two parts of a chocolate are equal. What does that tell us?","options":["One is bigger","They are the same size","They are double","One is smaller"],"answer":1,"explain":"Equal parts are exactly the same size."},{"kind":"numeric","prompt":"How many halves make one whole?","answer":2,"explain":"2 halves make one whole."},{"kind":"numeric","prompt":"Mukta has 12 marbles. Shabnam has half as many. How many marbles does Shabnam have?","answer":6,"explain":"Half of 12 is 6."},{"kind":"mcq","prompt":"10 marbles are ______ of 5 marbles. 🔮 Pick the right word.","options":["double","half","equal","a quarter"],"answer":0,"explain":"10 is two times 5, so it is double."},{"kind":"numeric","prompt":"Peehu has 16 flowers and ties a quarter of them. How many flowers does she tie?","answer":4,"explain":"A quarter of 16 is 4."},{"kind":"mcq","prompt":"I have less than double of 3 marbles. I have more than half of 8 marbles. How many marbles do I have?","options":["4 marbles","7 marbles","6 marbles","5 marbles"],"answer":3,"explain":"Double of 3 is 6 and half of 8 is 4, so I have 5."},{"kind":"mcq","prompt":"A chikki is cut into 4 equal parts. Shabnam eats 2 parts. What part did she eat?","options":["One half (2 quarters)","The whole chikki","Three quarters","One quarter"],"answer":0,"explain":"2 quarters make one half."}]}]},{"id":"hundredstwo3","index":8,"name":"House of Hundreds - II","subtitle":"Numbers up to 1000","emoji":"🏘️","palette":{"from":"#facc15","to":"#713f12"},"lessons":[{"id":"hb1","title":"Hundreds and Place Value","icon":"💯","kind":"lesson","story":"Akbar and Birbal see many crows in the sky! Birbal says there are 963 crows. Let us learn big numbers.","teach":[{"title":"Counting hundreds","body":"Count by hundreds: 100, 200, 300 ... 900. Ten hundreds make 1000!","visual":"🐦"},{"title":"Hundreds, tens, ones","body":"368 is 3 hundreds, 6 tens and 8 ones. That is 300 + 60 + 8.","visual":"🧱"}],"questions":[{"kind":"numeric","prompt":"100, 200, 300, 400, 500, ___ . What comes next?","answer":600,"explain":"After 500 comes 600."},{"kind":"mcq","prompt":"Birbal said 963 crows. How do we say 963?","options":["Six hundred ninety three","Nine hundred thirty six","Nine hundred sixty three","Three hundred sixty nine"],"answer":2,"explain":"9 hundreds, 6 tens and 3 ones is nine hundred sixty three."},{"kind":"numeric","prompt":"3 hundreds, 6 tens and 8 ones make which number?","answer":368,"explain":"300 + 60 + 8 = 368."},{"kind":"numeric","prompt":"What is 32 less than 400?","answer":368,"explain":"400 - 32 = 368."}]},{"id":"hb2","title":"Neighbours on the Number Line","icon":"📏","kind":"lesson","story":"Hungry cranes want to reach a worm and a fish. Use the number line to help them!","teach":[{"title":"Neighbouring numbers","body":"468 lies between 400 and 500. It also lies between 460 and 470.","visual":"📍"},{"title":"Jumps on the line","body":"A crane can jump in steps. From 667, 33 steps reach 700.","visual":"🐦"}],"questions":[{"kind":"mcq","prompt":"Between which two hundreds does 734 lie?","options":["700 and 800","800 and 900","730 and 740","600 and 700"],"answer":0,"explain":"734 is more than 700 and less than 800."},{"kind":"mcq","prompt":"Between which two fifties does 345 lie?","options":["400 and 450","350 and 400","340 and 350","300 and 350"],"answer":3,"explain":"345 is more than 300 and less than 350."},{"kind":"mcq","prompt":"Between which two tens does 899 lie?","options":["900 and 910","880 and 890","890 and 900","800 and 900"],"answer":2,"explain":"899 is more than 890 and less than 900."},{"kind":"numeric","prompt":"A crane is at 667. How many steps to reach 700?","answer":33,"explain":"700 - 667 = 33 steps."}]},{"id":"hb3","title":"Skip and Solve","icon":"🦘","kind":"lesson","story":"Teji and Jojo are resting. Ajji asks them to finish the number patterns. Let us help!","teach":[{"title":"Skip counting","body":"A pattern can jump by 10, 25 or 100 each time. Find the jump first!","visual":"🦘"}],"questions":[{"kind":"numeric","prompt":"730, 740, 750, ___ . The jump is 10. What comes next?","answer":760,"explain":"750 + 10 = 760."},{"kind":"numeric","prompt":"450, 550, 650, ___ . The jump is 100. What comes next?","answer":750,"explain":"650 + 100 = 750."},{"kind":"mcq","prompt":"Start at 750 and jump by 25. What comes after 800?","options":["810","805","825","850"],"answer":2,"explain":"800 + 25 = 825."},{"kind":"numeric","prompt":"995, 996, 997, 998, 999, ___ . What comes next?","answer":1000,"explain":"999 + 1 = 1000."}]},{"id":"hb4","title":"Make and Order Numbers","icon":"🧮","kind":"lesson","story":"Jojo has paper slips with 100, 10 and 1 on them. Let us make numbers with the slips!","teach":[{"title":"Slips make numbers","body":"4 slips of 100 and 2 slips of 10 make 420.","visual":"🧾"},{"title":"Smallest and largest","body":"With digits 3 and 8, the smallest 3-digit number is 333. The largest is 888.","visual":"🔢"}],"questions":[{"kind":"mcq","prompt":"Four slips of 100 and two slips of 10. What number is made?","options":["402","240","420","600"],"answer":2,"explain":"400 + 20 = 420."},{"kind":"numeric","prompt":"How many slips make 231? Use 100, 10 and 1 slips. (2 hundreds, 3 tens, 1 one)","answer":6,"explain":"2 + 3 + 1 = 6 slips."},{"kind":"numeric","prompt":"Use only the digits 3 and 8. What is the smallest 3-digit number you can make?","answer":333,"explain":"Using 3 for every digit gives the smallest number, 333."},{"kind":"mcq","prompt":"Which is the smallest number?","options":["833","388","338","383"],"answer":2,"explain":"All start with 3 or 8. 338 has the smallest tens and ones."}]},{"id":"hb5","title":"The Number Detective","icon":"🕵️","kind":"lesson","story":"Detective time! Teji and Jojo hunt for special numbers hiding in the Hundreds house.","teach":[{"title":"Special numbers","body":"353 and 868 read the same both ways. 111 and 222 are triplet digits.","visual":"🔍"},{"title":"Read the clues","body":"Use each clue to cut down the numbers until only one is left.","visual":"🧩"}],"questions":[{"kind":"mcq","prompt":"Which number reads the same from left to right and right to left?","options":["335","358","835","353"],"answer":3,"explain":"353 backwards is still 353."},{"kind":"mcq","prompt":"Which number has triplet digits?","options":["441","444","414","144"],"answer":1,"explain":"444 uses the same digit three times."},{"kind":"numeric","prompt":"I am century plus half century. Who am I?","answer":150,"explain":"100 + 50 = 150."},{"kind":"mcq","prompt":"I am between 400 and 450. I have 5 as a digit. Who am I?","options":["425","400","150","367"],"answer":0,"explain":"425 is between 400 and 450 and has the digit 5."}]},{"id":"hb6","title":"Word Numerals","icon":"🪔","kind":"lesson","story":"Ajji shows cards with words, not numbers. This is called Bhutasankhya. Can you crack the code?","teach":[{"title":"Bhutasankhya","body":"Words stand for digits. Moon = 1, Eyes = 2, Tri kala = 3, Directions = 4, Palm = 5.","visual":"🌙"},{"title":"Sapta svara","body":"Sapta svara means 7 musical notes, so it stands for 7. Write digits in card order.","visual":"🎵"}],"questions":[{"kind":"numeric","prompt":"Moon = 1 and Eyes = 2. What number do the cards Moon, Eyes show?","answer":12,"explain":"Moon is 1 and Eyes is 2, so 12."},{"kind":"mcq","prompt":"Which word card stands for 7?","options":["Moon","Eyes","Sapta svara","Palm"],"answer":2,"explain":"Sapta svara means seven musical notes."},{"kind":"numeric","prompt":"Moon = 1, Directions = 4, Eyes = 2. What number do these cards show?","answer":142,"explain":"Write the digits in card order: 1, 4, 2 makes 142."},{"kind":"mcq","prompt":"Eyes = 2 and Sapta svara = 7. Which cards make 27?","options":["Eyes, Sapta svara","Eyes, Palm","Moon, Sapta svara","Sapta svara, Eyes"],"answer":0,"explain":"27 starts with 2 (Eyes) and then 7 (Sapta svara)."}]},{"id":"hb-boss","title":"Boss: Crow Counter","icon":"🐦‍⬛","kind":"boss","boss":{"name":"Cunning Crow King","taunt":"Caw! Can you count my crows up to 1000?"},"story":"The Crow King flaps over the Hundreds house! Use all you know about big numbers to beat him.","teach":[{"title":"Big number review","body":"Use hundreds, tens and ones, the number line, patterns and clues to find numbers.","visual":"👑"}],"questions":[{"kind":"numeric","prompt":"2 hundreds, 5 tens and 9 ones make which number?","answer":259,"explain":"200 + 50 + 9 = 259."},{"kind":"mcq","prompt":"Between which two tens does 628 lie?","options":["610 and 620","600 and 700","620 and 630","630 and 640"],"answer":2,"explain":"628 is more than 620 and less than 630."},{"kind":"numeric","prompt":"825, 850, 875, ___ . The jump is 25. What comes next?","answer":900,"explain":"875 + 25 = 900."},{"kind":"mcq","prompt":"Use the digits 3 and 8. What is the largest 3-digit number?","options":["888","338","838","883"],"answer":0,"explain":"Using 8 for every digit gives the largest number, 888."},{"kind":"mcq","prompt":"Which number reads the same both ways?","options":["868","886","866","688"],"answer":0,"explain":"868 backwards is still 868."},{"kind":"numeric","prompt":"Moon = 1, Eyes = 2, Tri kala = 3. What number do the cards Moon, Eyes, Tri kala show?","answer":123,"explain":"The digits in card order are 1, 2, 3, so 123."},{"kind":"numeric","prompt":"What is 900 + 100?","answer":1000,"explain":"Ten hundreds make 1000."}]}]},{"id":"classparty3","index":9,"name":"Fun at Class Party!","subtitle":"Measuring length: metre, half, quarter","emoji":"🎉","palette":{"from":"#fb7185","to":"#881337"},"lessons":[{"id":"cp1","title":"Hands and Feet Rulers","icon":"🖐️","kind":"lesson","story":"Shelly and Adi are getting the class ready for a party! They need to measure the big table. 📏","teach":[{"title":"Measure with your body","body":"We can measure length with a hand span or a footstep. Count how many fit along the thing.","visual":"🖐️"},{"title":"Different hands, different counts","body":"A big hand span is longer than a small one. So Leena and Adi can get different numbers for the same table.","visual":"👣"}],"questions":[{"kind":"mcq","prompt":"Leena measures a table with her hand span. What does she count?","options":["How many colours the table has","How many chairs are near it","How many children are in the class","How many hand spans fit along the table"],"answer":3,"explain":"To measure length, we count how many hand spans fit along the table."},{"kind":"mcq","prompt":"Leena has a small hand. Adi has a big hand. Who gets MORE spans for the same table?","options":["Leena","Adi","Both get the same","Nobody can say"],"answer":0,"explain":"A small hand span is short, so more of them are needed to cover the table."},{"kind":"numeric","prompt":"Leena measures the table and gets 8 hand spans. Adi gets 6. How many more spans did Leena count?","answer":2,"explain":"8 take away 6 is 2, so Leena counted 2 more."},{"kind":"mcq","prompt":"Which is a good way to measure the length of the classroom floor?","options":["Look at its colour","Weigh it","Count footsteps along it","Count the windows"],"answer":2,"explain":"Footsteps laid one after another can measure a length."}]},{"id":"cp2","title":"Longest and Shortest Strings","icon":"🎀","kind":"lesson","story":"The class is decorating the green board with paper strings. 🎉 Help Shelly pick the right ones!","teach":[{"title":"Compare two strings","body":"Put the strings side by side. Start both at the same end. The one that goes further is longer.","visual":"🎀"},{"title":"Longest and shortest","body":"The longest string reaches the farthest. The shortest string stops first.","visual":"📏"}],"questions":[{"kind":"mcq","prompt":"Red string is 4 hand spans. Green string is 7 hand spans. Which is longer?","options":["Green string","Cannot tell","Red string","They are the same"],"answer":0,"explain":"7 is more than 4, so the green string is longer."},{"kind":"mcq","prompt":"Three strings are 5, 9 and 3 hand spans long. Which is the shortest?","options":["3 hand spans","5 hand spans","All are the same","9 hand spans"],"answer":0,"explain":"3 is the smallest number, so that string is the shortest."},{"kind":"mcq","prompt":"When you compare strings side by side, what must you do first?","options":["Start both from the same end","Fold one string","Tie them together","Colour them"],"answer":0,"explain":"Both strings must start at the same place to compare fairly."},{"kind":"numeric","prompt":"Shelly has 5 paper strings for the board. She hangs 3 of them. How many are left?","answer":2,"explain":"5 take away 3 is 2 strings left."}]},{"id":"cp3","title":"The Table and the Door","icon":"🚪","kind":"lesson","story":"Shelly and Adi cannot lift the heavy table! 🪑 Will it fit through the door? Let us use a thread.","teach":[{"title":"Measure without moving it","body":"We cannot always put two things side by side. Use a thread to measure one thing, then check the other.","visual":"🧵"},{"title":"Use the same unit","body":"Measure both with the same thread or the same hand span. Then compare the two numbers.","visual":"🚪"}],"questions":[{"kind":"mcq","prompt":"The heavy table cannot be lifted. How can Adi check if it fits the door?","options":["Measure both with the same thread","Guess by its colour","Push it hard","Ask it to move"],"answer":0,"explain":"A thread can be used to measure the table and the door, then we compare."},{"kind":"mcq","prompt":"The table is 7 hand spans wide. The door is 5 hand spans wide. Can the table go through the door straight?","options":["Nobody knows","No, the table is wider","Yes, the table is narrower","Yes, they are equal"],"answer":1,"explain":"7 is more than 5, so the table is wider than the door."},{"kind":"mcq","prompt":"How should we measure the table and the door to compare them fairly?","options":["Use the same unit for both things","Use a hand span for one and a foot for the other","Use a different thread each time","Look quickly"],"answer":0,"explain":"To compare, we must use the same unit for both."},{"kind":"mcq","prompt":"A table is longer AND wider than the door. How might it still go through?","options":["Paint it","Make the door smaller","It cannot ever","Tilt it and turn it sideways"],"answer":3,"explain":"Turning the table can help it pass through, as the story showed."}]},{"id":"cp4","title":"Bigger Strips, Faster Work","icon":"📜","kind":"lesson","story":"Measuring the saree for the curtain with a pencil takes so long! ⏰ Shelly needs a longer helper.","teach":[{"title":"A longer unit is faster","body":"A pencil is short, so we must count many pencils. A paper strip is twice a pencil, so we count fewer.","visual":"✏️"},{"title":"Double the strip","body":"Stick two strips together to make a longer one. An arm-long strip is even better for a big saree.","visual":"📜"}],"questions":[{"kind":"mcq","prompt":"Why is a long paper strip better than a pencil for measuring a saree?","options":["It is lighter","Fewer counts are needed","It has more colours","It smells nice"],"answer":1,"explain":"A longer unit covers more length each time, so we count less."},{"kind":"numeric","prompt":"A wall is 12 pencils long. One paper strip is 2 pencils long. How many strips make the wall?","answer":6,"explain":"12 pencils in groups of 2 gives 6 strips."},{"kind":"numeric","prompt":"A table is 10 pencils long. How many strips of 2 pencils make it?","answer":5,"explain":"10 in groups of 2 is 5 strips."},{"kind":"mcq","prompt":"Shelly sticks two strips of 2 pencils each together. How long is the new strip?","options":["3 pencils","1 pencil","4 pencils","2 pencils"],"answer":2,"explain":"2 pencils and 2 pencils make 4 pencils."}]},{"id":"cp5","title":"The Metre Rope","icon":"🪢","kind":"lesson","story":"Adi has an idea! 💡 A shopkeeper measures cloth with a metre rod. Let us make a rope that is one metre long.","teach":[{"title":"One metre","body":"A metre is a standard length. Mark one metre on a rope with two knots. The rope between the knots is one metre.","visual":"🪢"},{"title":"More or less than a metre","body":"A pencil is less than one metre. A bus is more than one metre. Some things are equal to one metre.","visual":"🚌"}],"questions":[{"kind":"mcq","prompt":"Which is MORE than one metre long?","options":["A bus 🚌","An eraser","A pencil ✏️","A coin 🪙"],"answer":0,"explain":"A bus is very long, much more than one metre."},{"kind":"mcq","prompt":"Which is LESS than one metre long?","options":["A pencil ✏️","A classroom door 🚪","A bus 🚌","A train 🚆"],"answer":0,"explain":"A pencil is small, so it is less than one metre."},{"kind":"mcq","prompt":"How can we check that a rope is one metre long?","options":["Keep it along a metre rod","Smell it","Tie five knots","Wash it"],"answer":0,"explain":"We place the rope along a metre rod and compare."},{"kind":"numeric","prompt":"Two ropes, each one metre long, are tied end to end for a bridge. How many metres long is it?","answer":2,"explain":"1 metre and 1 metre make 2 metres."}]},{"id":"cp6","title":"Half and Quarter Metre","icon":"✂️","kind":"lesson","story":"Time to cut rope for the party! ✂️ Fold the metre rope and make smaller pieces.","teach":[{"title":"Half a metre","body":"Fold a one metre rope in half. Each piece is a half metre. Two halves make one metre.","visual":"✂️"},{"title":"A quarter metre","body":"Fold the half metre in half again. Each piece is a quarter metre. Four quarters make one metre.","visual":"🧵"}],"questions":[{"kind":"numeric","prompt":"How many half metre ropes make one metre?","answer":2,"explain":"Two halves make one whole metre."},{"kind":"numeric","prompt":"How many quarter metre ropes make one metre?","answer":4,"explain":"Four quarters make one whole metre."},{"kind":"numeric","prompt":"You cut a one metre rope into 4 equal pieces. How many cuts did you make?","answer":3,"explain":"3 cuts make 4 pieces, like cutting a roti into 4."},{"kind":"numeric","prompt":"You have 3 quarter metre ropes. How many more make one metre?","answer":1,"explain":"4 quarters are needed, 4 take away 3 is 1."}]},{"id":"cp-boss","title":"Boss: The Party Measurer","icon":"🎉","kind":"boss","boss":{"name":"Captain Tangle","taunt":"Ha! Can you measure my twisty ropes?"},"story":"Captain Tangle has tied up all the party ropes in knots! 🪢 Use what you know about length to set them free.","teach":[{"title":"Length review","body":"Use the same unit to compare. A longer unit needs fewer counts. Two halves or four quarters make one metre.","visual":"📏"}],"questions":[{"kind":"mcq","prompt":"Leena has a small hand. Adi has a big hand. They both measure one table. Why can their counts differ?","options":["They used a metre rod","The table changes","Their hand spans are different sizes","Adi counts wrongly always"],"answer":2,"explain":"Different hand spans give different counts, so a standard unit is better."},{"kind":"mcq","prompt":"Strings are 6, 2 and 8 hand spans long. Which is the longest?","options":["All same","2 hand spans","8 hand spans","6 hand spans"],"answer":2,"explain":"8 is the biggest number, so that string is the longest."},{"kind":"numeric","prompt":"A wall is 12 pencils long. A paper strip is 2 pencils long. How many strips make the wall?","answer":6,"explain":"12 in groups of 2 is 6 strips."},{"kind":"mcq","prompt":"Which is LESS than one metre?","options":["A road 🛣️","A pencil ✏️","A bus 🚌","A train 🚆"],"answer":1,"explain":"A pencil is much shorter than one metre."},{"kind":"numeric","prompt":"How many quarter metre pieces make one metre?","answer":4,"explain":"Four quarters make one metre."},{"kind":"numeric","prompt":"You fold a one metre rope in half. How many half metre pieces do you get?","answer":2,"explain":"Folding in half gives 2 equal pieces."},{"kind":"mcq","prompt":"How can Adi check a heavy table fits the door without lifting it?","options":["Measure both with the same thread","Push the table","Guess","Wait for lunch"],"answer":0,"explain":"A thread measures both things so we can compare the numbers."}]}]},{"id":"fillinglifting3","index":10,"name":"Filling and Lifting","subtitle":"Litres, kilograms, heavy and light","emoji":"🥛","palette":{"from":"#c084fc","to":"#581c87"},"lessons":[{"id":"fl1","title":"Whose Glass Holds More?","icon":"🥛","kind":"lesson","story":"Nita and Monu visit Ritu's house. Ritu's mother gives them milk in different glasses. Who gets the most?","teach":[{"title":"Holds more, holds less","body":"A bigger glass holds more milk. A smaller glass holds less milk.","visual":"🥛"},{"title":"Pour to compare","body":"Pour each glass into same-sized cups. The glass that fills more cups holds the most.","visual":"🫗"}],"questions":[{"kind":"mcq","prompt":"Ritu's milk fills 3 cups. Monu's fills 2 cups. Nita's fills 1 cup. Who drank the most milk?","options":["All the same","Ritu","Nita","Monu"],"answer":1,"explain":"3 cups is more than 2 cups or 1 cup, so Ritu drank the most."},{"kind":"mcq","prompt":"Ritu's milk fills 3 cups. Monu's fills 2 cups. Nita's fills 1 cup. Who drank the least milk?","options":["All the same","Nita","Monu","Ritu"],"answer":1,"explain":"1 cup is the smallest, so Nita drank the least."},{"kind":"mcq","prompt":"Monu's glass fills 2 cups. Nita's glass fills 1 cup. Monu's glass holds ___ milk than Nita's glass.","options":["more","the same","less"],"answer":0,"explain":"2 cups is more than 1 cup, so Monu's glass holds more."},{"kind":"numeric","prompt":"Ritu's glass holds 5 cups of milk. Nita's glass holds 3 cups. How many more cups does Ritu's glass hold?","answer":2,"explain":"5 - 3 = 2 cups more."}]},{"id":"fl2","title":"Fill It Up!","icon":"🍋","kind":"lesson","story":"Lina is serving lemonade at the mela. She has a jug, a bowl, a ladle and glasses. How many pours will she need?","teach":[{"title":"Small vessels fill big ones","body":"A small ladle can fill a big bowl, but it takes many pours. A big jug can fill many small glasses.","visual":"🥄"},{"title":"The amount stays the same","body":"Pour a jug into glasses and the lemonade does not change. Pour it back and it is the same amount.","visual":"🍋"}],"questions":[{"kind":"numeric","prompt":"One jug fills 4 glasses of lemonade. How many glasses can 3 jugs fill?","answer":12,"explain":"3 jugs of 4 glasses each: 4 + 4 + 4 = 12 glasses."},{"kind":"numeric","prompt":"One glass needs 2 ladles of lemonade. How many ladles are needed to fill 4 glasses?","answer":8,"explain":"4 glasses with 2 ladles each: 2 + 2 + 2 + 2 = 8 ladles."},{"kind":"numeric","prompt":"A bowl holds 6 ladles of lemonade. Lina has 12 ladles of lemonade. How many bowls can she fill?","answer":2,"explain":"6 ladles fill one bowl and 6 more fill another. 12 / 6 = 2 bowls."},{"kind":"mcq","prompt":"Lina pours a full jug of lemonade into glasses. Then she pours it all back into the jug. What happens?","options":["The jug is full again with the same amount","The lemonade disappears","The jug has less lemonade","The jug has more lemonade"],"answer":0,"explain":"Pouring from one vessel to another does not change the amount."}]},{"id":"fl3","title":"The 1 Litre Bottle","icon":"🍼","kind":"lesson","story":"Nita has a bottle that holds exactly 1 litre. Can it help her measure the jug, the glass and the bucket?","teach":[{"title":"A litre measures liquids","body":"We measure how much water or milk a vessel holds in litres. A 1 litre bottle is our measuring tool.","visual":"🍼"},{"title":"More, less or exactly","body":"Pour the bottle into a vessel to check. A vessel can hold more than, less than or exactly 1 litre.","visual":"🪣"}],"questions":[{"kind":"mcq","prompt":"Nita pours the 1 litre bottle into a jug. The jug fills up exactly. How much does the jug hold?","options":["Less than 1 litre","Exactly 1 litre","More than 1 litre"],"answer":1,"explain":"The bottle filled the jug exactly, so the jug holds 1 litre."},{"kind":"mcq","prompt":"Which one holds less than 1 litre of water? 🥛 a small glass or 🪣 a big bucket","options":["A small glass","A big bucket","Both hold the same"],"answer":0,"explain":"A small glass is much smaller than a litre bottle."},{"kind":"mcq","prompt":"Why does the milkman use a measuring cup to give milk?","options":["To make the milk colder","To make the milk sweeter","To give the right amount of milk each time"],"answer":2,"explain":"A measuring cup helps measure the same amount every time."},{"kind":"numeric","prompt":"Ritu's mother has 5 litres of milk. She uses 2 litres. How many litres are left?","answer":3,"explain":"5 - 2 = 3 litres left."}]},{"id":"fl4","title":"Half and Quarter Litre","icon":"🥤","kind":"lesson","story":"Rani has a half litre mug and a quarter litre glass. She wants to fill a 1 litre bottle with them.","teach":[{"title":"Half a litre","body":"Two half litre mugs make 1 litre. A half litre is half of a litre.","visual":"☕"},{"title":"A quarter litre","body":"Four quarter litre glasses make 1 litre. A quarter litre is the smallest of the three.","visual":"🥛"}],"questions":[{"kind":"numeric","prompt":"How many half litre mugs fill a 1 litre bottle?","answer":2,"explain":"Half + half = 1 litre, so 2 mugs."},{"kind":"numeric","prompt":"How many quarter litre glasses fill a 1 litre bottle?","answer":4,"explain":"Four quarter litres make 1 litre."},{"kind":"mcq","prompt":"Which holds the most water?","options":["1 litre","Quarter litre","Half litre"],"answer":0,"explain":"1 litre is more than half a litre and more than a quarter litre."},{"kind":"numeric","prompt":"Rani fills 8 quarter litre glasses. How many litres of water is that?","answer":2,"explain":"4 glasses make 1 litre, so 8 glasses make 2 litres."}]},{"id":"fl5","title":"Heavy or Light?","icon":"⚖️","kind":"lesson","story":"Chintu is holding 3 textbooks in one hand and a pencil box in the other. One hand is going down. Why?","teach":[{"title":"Heavier and lighter","body":"Heavier things pull down more. The hand holding the heavier thing goes lower.","visual":"📚"},{"title":"The pan balance","body":"On a pan balance, the heavier side goes down. We can balance an object with matchboxes or coins to weigh it.","visual":"⚖️"}],"questions":[{"kind":"mcq","prompt":"Chintu holds 3 textbooks 📚 in one hand and a pencil box in the other. Which hand goes lower?","options":["The hand with the textbooks","The hand with the pencil box","Both stay level"],"answer":0,"explain":"The books are heavier, so that hand goes down."},{"kind":"mcq","prompt":"On a pan balance, an apple is on one side and a watermelon is on the other. What happens?","options":["The watermelon side goes down","The apple side goes down","Both sides stay level"],"answer":0,"explain":"The watermelon is heavier, so its side goes down."},{"kind":"numeric","prompt":"A pencil box balances with 6 matchboxes of sand. A spoon balances with 2 matchboxes. How many matchboxes balance both together?","answer":8,"explain":"6 + 2 = 8 matchboxes."},{"kind":"mcq","prompt":"A spoon balances 2 matchboxes. 4 marbles balance 3 matchboxes. A pencil box balances 6. Which order is lightest to heaviest?","options":["Pencil box, marbles, spoon","Spoon, marbles, pencil box","Marbles, spoon, pencil box"],"answer":1,"explain":"2 is less than 3, and 3 is less than 6."}]},{"id":"fl6","title":"Kilograms and Tricky Balls","icon":"🧂","kind":"lesson","story":"Montu has a 1 kilogram salt packet and a pan balance. He also has a puzzle with three tricky balls.","teach":[{"title":"Kilogram, half and quarter","body":"We weigh heavy things in kilograms. Two half kilogram packets make 1 kilogram. Four quarter kilogram packets make 1 kilogram.","visual":"🧂"},{"title":"Find the heavy one","body":"Put one ball on each pan. If the pans stay level, the ball left out is the heavy one.","visual":"⚽"}],"questions":[{"kind":"numeric","prompt":"Each daal packet weighs half a kilogram. How many daal packets weigh 1 kilogram together?","answer":2,"explain":"Half + half = 1 kilogram, so 2 packets."},{"kind":"numeric","prompt":"Each tea packet weighs a quarter kilogram. How many tea packets weigh 1 kilogram together?","answer":4,"explain":"Four quarters make 1 kilogram."},{"kind":"mcq","prompt":"Which is likely to be lighter than 1 kilogram? ✏️ a pencil or 🌾 a big sack of rice","options":["A pencil","A big sack of rice","Both weigh the same"],"answer":0,"explain":"A pencil is very light, much less than 1 kilogram."},{"kind":"mcq","prompt":"Montu has 3 balls. One is heavier and 2 are equal. He puts one ball on each pan and the pans stay level. Which is the heavy ball?","options":["The ball on the left pan","The ball on the right pan","The ball he left out"],"answer":2,"explain":"If the two weigh the same, the heavy one must be the one left out."}]},{"id":"fl-boss","title":"Boss: The Giant Jug","icon":"🏺","kind":"boss","boss":{"name":"The Giant Jug","taunt":"Can you fill me up and lift me up?"},"story":"A giant jug blocks the way to the mela. Answer questions about filling and lifting to get past it!","teach":[{"title":"Remember!","body":"Litres tell how much a vessel holds. Kilograms tell how heavy something is.","visual":"🥛"}],"questions":[{"kind":"mcq","prompt":"Glass A fills 4 cups and glass B fills 6 cups. Which glass holds more?","options":["Glass B","Glass A","Both hold the same"],"answer":0,"explain":"6 cups is more than 4 cups."},{"kind":"numeric","prompt":"One jug fills 4 glasses. How many glasses can 3 jugs fill?","answer":12,"explain":"4 + 4 + 4 = 12 glasses."},{"kind":"mcq","prompt":"A vessel is filled exactly by the 1 litre bottle. How much does it hold?","options":["Exactly 1 litre","Less than 1 litre","More than 1 litre"],"answer":0,"explain":"It takes just one full bottle, so it holds exactly 1 litre."},{"kind":"numeric","prompt":"How many quarter litre glasses fill a 1 litre bottle?","answer":4,"explain":"Four quarter litres make 1 litre."},{"kind":"mcq","prompt":"On a pan balance, which side goes down?","options":["The lighter side","The heavier side","The left side always"],"answer":1,"explain":"Heavier things pull their side down."},{"kind":"numeric","prompt":"Each tea packet weighs a quarter kilogram. How many packets make 2 kilograms?","answer":8,"explain":"4 packets make 1 kilogram, so 8 packets make 2 kilograms."},{"kind":"mcq","prompt":"Which is likely to weigh more than 1 kilogram? 🍎 one apple or 🍉 a big watermelon","options":["A big watermelon","One apple","Both weigh the same"],"answer":0,"explain":"A big watermelon is very heavy, more than 1 kilogram."}]}]},{"id":"giveandtake3","index":11,"name":"Give and Take","subtitle":"Adding and subtracting 3-digit numbers, money","emoji":"🪙","palette":{"from":"#38bdf8","to":"#0c4a6e"},"lessons":[{"id":"gt1","title":"Saplings to Add","icon":"🌱","kind":"lesson","story":"Kishan runs a big plant nursery. He brings new saplings from a friend's village. Help him count!","teach":[{"title":"Add ones, then tens, then hundreds","body":"364 + 52: 4 + 2 = 6 ones. 6 tens + 5 tens = 11 tens. 3 hundreds + 1 more hundred = 4 hundreds.","visual":"🌱"},{"title":"10 tens make 1 hundred","body":"When tens go past 9, swap 10 tens for 1 hundred. So 364 + 52 = 416.","visual":"🧱"}],"questions":[{"kind":"numeric","prompt":"Kishan has 364 saplings. He brings 52 more. How many saplings does he have now? 🌱","answer":416,"explain":"364 + 52 = 416 saplings."},{"kind":"mcq","prompt":"What is 6 tens + 5 tens?","options":["12 tens","11 tens","1 ten","10 tens"],"answer":1,"explain":"6 + 5 = 11, so 11 tens. That is 1 hundred and 1 ten."},{"kind":"numeric","prompt":"Kishan has 245 saplings. He gets 34 more. How many saplings in all? 🌿","answer":279,"explain":"245 + 34 = 279 saplings."},{"kind":"numeric","prompt":"A van brings 327 saplings. Another van brings 60 saplings. How many saplings came in all? 🚚","answer":387,"explain":"327 + 60 = 387 saplings."}]},{"id":"gt2","title":"Taking Away Saplings","icon":"📦","kind":"lesson","story":"A school ordered 230 saplings. Kishan has packed some. How many are left to pack?","teach":[{"title":"Not enough ones? Open a ten","body":"To take 5 ones from 0 ones, change 1 ten into 10 ones. Now you can take them away.","visual":"🔟"},{"title":"Open a hundred if you need to","body":"1 hundred block opens into 10 tens. 230 - 75: 230 - 5 = 225, then 225 - 70 = 155.","visual":"🧮"}],"questions":[{"kind":"numeric","prompt":"The school orders 230 saplings. 75 are packed. How many more must be packed? 📦","answer":155,"explain":"230 - 75 = 155 saplings."},{"kind":"mcq","prompt":"A hundreds block is opened. How many tens blocks do you get?","options":["5 tens","100 tens","10 tens","1 ten"],"answer":2,"explain":"1 hundred is the same as 10 tens."},{"kind":"numeric","prompt":"Kishan has 456 saplings. He gives away 63. How many are left? 🌱","answer":393,"explain":"456 - 63 = 393 saplings."},{"kind":"numeric","prompt":"Kishan has 180 herb saplings. His friend has 45. How many more does Kishan have? 🌿","answer":135,"explain":"To find how many more, subtract: 180 - 45 = 135."}]},{"id":"gt3","title":"Grid Jumps","icon":"🔢","kind":"lesson","story":"Kishan's number grid shows 451 to 530. Hop around it with jumps of 1, 10 and 100!","teach":[{"title":"Jumps of 1, 10 and 100","body":"Add 1: the ones digit goes up. Add 10: the tens digit goes up. Add 100: the hundreds digit goes up.","visual":"🦘"},{"title":"Going down the grid","body":"Taking away 10 moves one row down on the grid. 519 - 40 means four rows down: 479.","visual":"⬇️"}],"questions":[{"kind":"numeric","prompt":"What is 456 + 10? 🔢","answer":466,"explain":"Adding 10 changes the tens digit: 456 becomes 466."},{"kind":"numeric","prompt":"Start at 269. Add 100. Where do you land?","answer":369,"explain":"Adding 100 changes the hundreds digit: 369."},{"kind":"mcq","prompt":"Which digit changes when you add 10 to 289?","options":["No digit changes","The hundreds digit","The tens digit","The ones digit"],"answer":2,"explain":"Adding 10 adds one ten. 289 + 10 = 299, and the tens digit changed."},{"kind":"numeric","prompt":"What is 519 - 40? 🔢","answer":479,"explain":"519 - 40 = 479. Take away 4 tens."}]},{"id":"gt4","title":"Notes and Coins","icon":"💵","kind":"lesson","story":"Long ago, Jadupur villagers swapped things. Now we use notes and coins. Let's go shopping!","teach":[{"title":"Money helps us buy things","body":"Notes and coins have different values. A ₹10 note can buy 1 hawa mithai or 10 toffees.","visual":"🪙"},{"title":"Many ways to pay","body":"5 notes of ₹100 make one ₹500 note. You can pay the same amount in many ways.","visual":"💵"}],"questions":[{"kind":"numeric","prompt":"How many ₹100 notes make one ₹500 note? 💵","answer":5,"explain":"100 + 100 + 100 + 100 + 100 = 500, so 5 notes."},{"kind":"mcq","prompt":"Salma pays ₹100 for 2 milk bottles. Kiran pays ₹100 for 1 basket of pomegranates. Which costs more, 1 bottle or 1 basket? 🥛🍎","options":["The basket of pomegranates","They cost the same","One milk bottle"],"answer":0,"explain":"One bottle is half of ₹100, which is ₹50. The basket costs ₹100."},{"kind":"numeric","prompt":"A ₹10 note buys 10 toffees. How many rupees does 1 toffee cost? 🍬","answer":1,"explain":"10 rupees shared by 10 toffees is 1 rupee each."},{"kind":"mcq","prompt":"Which way pays exactly ₹28?","options":["1 note of ₹10 and 8 coins of ₹1","2 notes of ₹10 and 5 coins of ₹1","3 notes of ₹10 and 8 coins of ₹1","2 notes of ₹10 and 8 coins of ₹1"],"answer":3,"explain":"20 + 8 = 28 rupees."}]},{"id":"gt5","title":"Peter Uncle's Shop","icon":"🏪","kind":"lesson","story":"Peter uncle keeps money in his box. Help him add, subtract and give back change!","teach":[{"title":"Draw a box diagram first","body":"Draw one big box for the whole amount. Draw small boxes for the parts. Then add or subtract.","visual":"📦"},{"title":"Add to join, subtract to find the rest","body":"Joining two amounts? Add. Finding how much is left, or the change? Subtract.","visual":"💰"}],"questions":[{"kind":"numeric","prompt":"In the morning Peter uncle has ₹380. By afternoon he has ₹625. How much did he earn since morning? 💰","answer":245,"explain":"625 - 380 = 245 rupees."},{"kind":"numeric","prompt":"Peter uncle sells rice for ₹520 and sugar for ₹135. How much money does he get? 🍚","answer":655,"explain":"520 + 135 = 655 rupees."},{"kind":"numeric","prompt":"Reena buys groceries for ₹307. She gives a ₹500 note. How much change does she get back? 🛒","answer":193,"explain":"500 - 307 = 193 rupees."},{"kind":"numeric","prompt":"Shireen has ₹120 in her piggy bank. She adds ₹100 each week for 4 weeks. How much does she have now? 🐷","answer":520,"explain":"4 weeks is ₹400. 120 + 400 = 520 rupees."}]},{"id":"gt6","title":"Estimate and Compare","icon":"🎯","kind":"lesson","story":"Kishan wants a quick guess before he counts. Can you estimate and compare without adding?","teach":[{"title":"Estimate to the nearest hundred","body":"Look at the tens digit. 50 or more? Go up to the next hundred. Less than 50? Stay down.","visual":"🎯"},{"title":"Compare without calculating","body":"373 + 23 and 373 + 40 start the same. Adding 40 gives more than adding 23.","visual":"⚖️"}],"questions":[{"kind":"mcq","prompt":"156 + 34 = 190. What is 190 to the nearest hundred?","options":["100","190","200","300"],"answer":2,"explain":"The tens digit is 9, so go up to 200."},{"kind":"mcq","prompt":"125 - 15 = 110. What is 110 to the nearest hundred?","options":["0","200","100","110"],"answer":2,"explain":"The tens digit is 1, so stay at 100."},{"kind":"mcq","prompt":"Without adding, which is more?","options":["204 + 30","They are equal","204 + 10"],"answer":0,"explain":"Both start at 204. Adding 30 gives more than adding 10."},{"kind":"mcq","prompt":"Which one is equal to 450 - 50?","options":["350 + 40","450 - 40","400 + 50","350 + 50"],"answer":3,"explain":"450 - 50 = 400 and 350 + 50 = 400."}]},{"id":"gt-boss","title":"The Barter Bandit","icon":"🪙","kind":"boss","boss":{"name":"Bartu the Barter Bandit","taunt":"I only swap things. Can you give and take with numbers?"},"story":"Bartu the Barter Bandit hides Kishan's saplings and money box. Beat his sums to win them back!","teach":[{"title":"Give and take review","body":"Add to join amounts. Subtract to find what is left or the change. Estimate with the tens digit.","visual":"🪙"}],"questions":[{"kind":"numeric","prompt":"Kishan has 273 saplings. He brings 45 more. How many does he have? 🌱","answer":318,"explain":"273 + 45 = 318."},{"kind":"numeric","prompt":"Kishan has 340 saplings. He gives 58 to a school. How many are left? 🌿","answer":282,"explain":"340 - 58 = 282."},{"kind":"numeric","prompt":"Peter uncle saves ₹250, then ₹125, then ₹350. How much has he saved in all? 💰","answer":725,"explain":"250 + 125 + 350 = 725 rupees."},{"kind":"numeric","prompt":"Meena pays ₹260 with a ₹500 note. How much change does she get? 💵","answer":240,"explain":"500 - 260 = 240 rupees."},{"kind":"mcq","prompt":"205 + 215 is about how much, to the nearest hundred?","options":["400","300","500","200"],"answer":0,"explain":"205 + 215 = 420. The tens digit is 2, so it is about 400."},{"kind":"numeric","prompt":"What is 478 + 10? 🔢","answer":488,"explain":"Adding 10 changes the tens digit: 488."},{"kind":"mcq","prompt":"Without calculating, which is more?","options":["816 - 200","615 - 200","They are equal"],"answer":0,"explain":"Both take away 200. 816 is bigger than 615, so 816 - 200 is more."}]}]},{"id":"timegoeson3","index":12,"name":"Time Goes On","subtitle":"Calendar, clock and age","emoji":"🕰️","palette":{"from":"#f59e0b","to":"#78350f"},"lessons":[{"id":"tg1","title":"Days on the Calendar","icon":"📅","kind":"lesson","story":"Appa bought a new calendar, but July is missing! Help Hetal read the days and dates.","teach":[{"title":"Seven days in a week","body":"A week has 7 days: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday. Then the week starts again.","visual":"📅"},{"title":"Same day, 7 days later","body":"If July 1 is a Monday, then July 8 is also a Monday. Add 7 to jump to the same day next week.","visual":"➕"}],"questions":[{"kind":"numeric","prompt":"How many days are there in one week? 📅","answer":7,"explain":"A week has 7 days."},{"kind":"mcq","prompt":"Which day comes after Saturday?","options":["Thursday","Sunday","Friday","Monday"],"answer":1,"explain":"Sunday comes right after Saturday."},{"kind":"mcq","prompt":"July 1, 2024 is a Monday. What day is July 8, 2024?","options":["Monday","Tuesday","Sunday","Thursday"],"answer":0,"explain":"8 is 7 more than 1, so it is the same day, Monday."},{"kind":"numeric","prompt":"In July 2024, Sundays fall on 7, 14, 21 and 28. How many Sundays are there?","answer":4,"explain":"The dates 7, 14, 21 and 28 make 4 Sundays."},{"kind":"mcq","prompt":"Thursdays in July 2024 are 4, 11 and 18. What is the next Thursday date?","options":["25","26","28","24"],"answer":0,"explain":"18 + 7 = 25."}]},{"id":"tg2","title":"Months and Years","icon":"🗓️","kind":"lesson","story":"Amma points at the calendar. Which months are there in a whole year? Let us count them!","teach":[{"title":"12 months in a year","body":"January, February, March, April, May, June, July, August, September, October, November, December. That is 12 months.","visual":"🗓️"},{"title":"Days and weeks in a year","body":"A year has 365 days. That is 52 full weeks. February has fewer than 30 days.","visual":"🌍"}],"questions":[{"kind":"numeric","prompt":"How many months are there in one year? 🗓️","answer":12,"explain":"A year has 12 months."},{"kind":"mcq","prompt":"Which month comes right after June?","options":["April","August","July","May"],"answer":2,"explain":"The order is June, then July."},{"kind":"mcq","prompt":"Which month has less than 30 days?","options":["March","July","February","April"],"answer":2,"explain":"February has 28 or 29 days, which is less than 30."},{"kind":"numeric","prompt":"How many days are there in a normal year?","answer":365,"explain":"A normal year has 365 days."},{"kind":"mcq","prompt":"Hetal says a year has 53 weeks. What is the right number of full weeks?","options":["12","50","53","52"],"answer":3,"explain":"52 weeks make 364 days, so a year has 52 full weeks."},{"kind":"mcq","prompt":"Which stays the same in every year's calendar?","options":["The day a birthday falls on","The year number","There are 7 days in a week","The day 1 January falls on"],"answer":2,"explain":"Days in a week is always 7. The year number and weekdays change."}]},{"id":"tg3","title":"Dates and Ages","icon":"🎂","kind":"lesson","story":"Bincy has a birth certificate. Let us read her date of birth and work out her age!","teach":[{"title":"Reading a date","body":"02/05/2015 is written day, month, year. It means 2 May 2015.","visual":"📜"},{"title":"Finding age","body":"Take away the birth year from the year now. Bincy was born in 2015, so in 2025 she is 10.","visual":"🎂"}],"questions":[{"kind":"mcq","prompt":"02/05/2015 is written day, month, year. What date is this?","options":["2 June 2015","5 February 2015","2 May 2015","5 May 2012"],"answer":2,"explain":"The first number is the day (2) and the second is the month (May)."},{"kind":"numeric","prompt":"Bincy was born on 2 May 2015. How old is she on 2 May 2025?","answer":10,"explain":"2025 - 2015 = 10 years."},{"kind":"numeric","prompt":"Bincy turns 8 on her eighth birthday. In which year is it? (Born in 2015)","answer":2023,"explain":"2015 + 8 = 2023."},{"kind":"numeric","prompt":"Bincy was born on 2 May. The certificate was made on 18 May. After how many days?","answer":16,"explain":"18 - 2 = 16 days."},{"kind":"numeric","prompt":"Hetal is twice as old as her brother. She is also 10 years older. How old is Hetal? (Brother is 10)","answer":20,"explain":"Brother is 10. Twice 10 is 20, and 20 is 10 more than 10."}]},{"id":"tg4","title":"Reading the Clock","icon":"🕰️","kind":"lesson","story":"Hetal wakes up with the morning clock. What time is it on the clock face?","teach":[{"title":"Two hands","body":"The short hand is the hour hand. The long hand is the minute hand. An hour has 60 minutes.","visual":"🕰️"},{"title":"O'clock, quarter and half","body":"At 7 o'clock the minute hand is on 12. Quarter past 8 is 8:15. Half past 8 is 8:30.","visual":"⏰"}],"questions":[{"kind":"numeric","prompt":"How many minutes are there in 1 hour? ⏰","answer":60,"explain":"1 hour has 60 minutes."},{"kind":"mcq","prompt":"Which hand on the clock is the long one?","options":["Minute hand","Hour hand","Both are long","Neither"],"answer":0,"explain":"The long hand is the minute hand."},{"kind":"mcq","prompt":"Hetal wakes at 7 o'clock. Where does the minute hand point?","options":["On 12","On 7","On 3","On 6"],"answer":0,"explain":"At an o'clock time, the minute hand is on 12."},{"kind":"mcq","prompt":"Half past 8 is written as","options":["6:30","8:30","8:45","8:15"],"answer":1,"explain":"Half an hour is 30 minutes, so half past 8 is 8:30."},{"kind":"mcq","prompt":"Quarter past 8 is written as","options":["8:05","8:15","8:30","8:45"],"answer":1,"explain":"A quarter of an hour is 15 minutes, so it is 8:15."}]},{"id":"tg5","title":"How Many Minutes?","icon":"⏱️","kind":"lesson","story":"Hetal started breakfast at 7:00 and finished at 7:15. How long did it take?","teach":[{"title":"Count the minutes","body":"From 7:00 to 7:15 is 15 minutes. From 7:00 to 7:30 is 30 minutes.","visual":"⏱️"},{"title":"Hours pass too","body":"From 4 o'clock to 5 o'clock is 1 hour. That is 60 minutes.","visual":"🌞"}],"questions":[{"kind":"numeric","prompt":"Hetal ate breakfast from 7:00 to 7:15. How many minutes did she take?","answer":15,"explain":"15 - 0 = 15 minutes."},{"kind":"numeric","prompt":"School period starts at 9:00 and ends at 9:45. How many minutes is that?","answer":45,"explain":"From 9:00 to 9:45 is 45 minutes."},{"kind":"numeric","prompt":"Hetal plays from 4:00 to 4:30. How many minutes does she play?","answer":30,"explain":"Half an hour is 30 minutes."},{"kind":"numeric","prompt":"Hetal wakes up at 6 o'clock and goes to school at 8 o'clock. How many hours pass?","answer":2,"explain":"8 - 6 = 2 hours."},{"kind":"mcq","prompt":"The clock shows 3:00. What time will it be after 1 hour?","options":["4:00","3:30","2:00","3:15"],"answer":0,"explain":"1 hour after 3:00 is 4:00."}]},{"id":"tg6","title":"Long and Short Times","icon":"⏳","kind":"lesson","story":"At Nani's house, Hetal sees a sweater and seeds. Some jobs take minutes. Some take months!","teach":[{"title":"Minutes to months","body":"Taking a shower takes minutes. A school period takes about 40 minutes. Knitting a sweater can take two months.","visual":"🧶"},{"title":"Two kinds of clocks","body":"A digital clock shows time with digits. An analog clock shows time with hands. A sand clock also measures time.","visual":"⏳"}],"questions":[{"kind":"mcq","prompt":"Which takes the longest time?","options":["Taking a shower","Eating a fruit 🍎","Brushing teeth","Knitting a sweater"],"answer":3,"explain":"Knitting a sweater takes months."},{"kind":"mcq","prompt":"Which job takes only minutes?","options":["Knitting a sweater 🧶","Growing cabbage 🥬","Changing summer to winter","Brushing teeth 🪥"],"answer":3,"explain":"Brushing teeth takes only a few minutes."},{"kind":"numeric","prompt":"Radish takes 2 weeks to grow. How many days is that?","answer":14,"explain":"2 weeks = 2 x 7 = 14 days."},{"kind":"mcq","prompt":"A clock that shows time using digits is called","options":["an analog clock","a sand clock","a digital clock","a calendar"],"answer":2,"explain":"A digital clock uses digits, like 07:15."},{"kind":"mcq","prompt":"A clock with hour and minute hands is called","options":["an analog clock","a digital clock","a calendar","a ruler"],"answer":0,"explain":"Clocks with hands are analog clocks."}]},{"id":"tg-boss","title":"Master of Time","icon":"👑","kind":"boss","boss":{"name":"Tick-Tock the Time Keeper","taunt":"Can you keep up with my ticking hands?"},"story":"Tick-Tock the Time Keeper hides the missing July page! Answer well to bring it back.","teach":[{"title":"Time review","body":"7 days make a week and 12 months make a year. An hour has 60 minutes. Half past is 30 and quarter past is 15.","visual":"🕰️"}],"questions":[{"kind":"mcq","prompt":"July 1, 2024 is a Monday. Which day is July 22, 2024?","options":["Tuesday","Sunday","Saturday","Monday"],"answer":3,"explain":"22 = 1 + 21 and 21 is 3 weeks, so it is Monday again."},{"kind":"mcq","prompt":"July 22, 2024 is a Monday. Three days later is July 25. Which day is it?","options":["Wednesday","Thursday","Sunday","Friday"],"answer":1,"explain":"Monday, Tuesday, Wednesday, Thursday. Three days after Monday is Thursday."},{"kind":"numeric","prompt":"A school closes on July 7. It opens 15 days later. What is the opening date in July?","answer":22,"explain":"7 + 15 = 22, so school opens on July 22."},{"kind":"numeric","prompt":"How many months are there in a year?","answer":12,"explain":"A year has 12 months."},{"kind":"numeric","prompt":"Bincy was born in 2015. How old is she in 2030?","answer":15,"explain":"2030 - 2015 = 15 years."},{"kind":"numeric","prompt":"Quarter past 8 is 8:15. How many minutes past 8 is that?","answer":15,"explain":"8:15 is 15 minutes after 8."},{"kind":"mcq","prompt":"Which is the longest time?","options":["2 months","2 weeks","2 days","2 hours"],"answer":0,"explain":"A month is longer than a week, a day or an hour."}]}]},{"id":"surajkund3","index":13,"name":"The Surajkund Fair","subtitle":"Symmetry, tiling and maps","emoji":"🎪","palette":{"from":"#ef4444","to":"#7f1d1d"},"lessons":[{"id":"sk1","title":"Symmetrical Malas","icon":"📿","kind":"lesson","story":"Soni and Avi reach a stall at the Surajkund Fair. A man and a woman are making colourful malas!","teach":[{"title":"Two equal halves","body":"A thing is symmetrical when its two halves are exactly the same. Fold it in the middle and the halves match.","visual":"🦋"},{"title":"Symmetrical malas","body":"A mala has 8 beads. In a symmetrical mala, the left half and right half match like a mirror.","visual":"📿"}],"questions":[{"kind":"mcq","prompt":"Which mala is symmetrical?","options":["🔵🔴🔴🔴🔴🔴🔵🔵","🔴🔵🔴🔵🔴🔵🔴🔵","🔴🔴🔵🔵🔵🔵🔴🔴","🔴🔴🔴🔴🔵🔵🔵🔵"],"answer":2,"explain":"The left half matches the right half, like a mirror."},{"kind":"numeric","prompt":"A symmetrical mala has 8 beads. Its left half is 🔴🔴🔵🔴. How many 🔴 beads are in the whole mala?","answer":6,"explain":"The left half has 3 red. The right half is the same, so 3 + 3 = 6."},{"kind":"mcq","prompt":"Make a symmetrical mala with 6 🔴 and 2 🔵. Which one works?","options":["🔵🔵🔴🔴🔴🔴🔴🔴","🔵🔴🔴🔴🔴🔴🔴🔵","🔴🔴🔴🔴🔴🔵🔴🔵","🔴🔴🔴🔴🔴🔴🔵🔵"],"answer":1,"explain":"Only the mala with blue at both ends has matching halves."},{"kind":"mcq","prompt":"Why is 🔴🔴🔴🔴🔵🔵🔵🔵 not symmetrical?","options":["It has 10 beads","It has only one colour","It has too many beads","The left half is red and the right half is blue, so they do not match"],"answer":3,"explain":"A symmetrical mala needs both halves to match."}]},{"id":"sk2","title":"Rangoli and Fold Lines","icon":"🌸","kind":"lesson","story":"At the Tamil Nadu stall, Amma draws a kolam. Can you spot the line that splits it into equal halves?","teach":[{"title":"The fold line","body":"A line that cuts a shape into two equal halves is a fold line. Fold on it and one half sits on the other.","visual":"📏"},{"title":"Finish the rangoli","body":"To finish a symmetrical rangoli, draw the other half exactly like the first half, as if in a mirror.","visual":"🌸"}],"questions":[{"kind":"mcq","prompt":"Soni folds a rangoli on its middle line. One half sits exactly on the other. What is the rangoli?","options":["Not symmetrical","Symmetrical","Broken","Too small"],"answer":1,"explain":"Halves that fit exactly on each other make it symmetrical."},{"kind":"numeric","prompt":"One half of a rangoli has 5 🌸. The other half is exactly the same. How many 🌸 in the whole rangoli?","answer":10,"explain":"5 + 5 = 10 flowers."},{"kind":"mcq","prompt":"Fold line is |. Left side: 🟡🔴🔵 |  Which right side makes it symmetrical?","options":["🔴🔵🟡","🟡🔴🔵","🔵🟡🔴","🔵🔴🟡"],"answer":3,"explain":"The right side is the left side in reverse order, like a mirror."},{"kind":"mcq","prompt":"Kolam is a rangoli from which state?","options":["Haryana","Kerala","Uttarakhand","Tamil Nadu"],"answer":3,"explain":"Kolam is from Tamil Nadu. Pookalam is from Kerala."}]},{"id":"sk3","title":"Masks and Letters","icon":"🎭","kind":"lesson","story":"Soni and Avi wear masks at the fair. Soni sees well, but Avi can only see with one eye!","teach":[{"title":"Symmetrical mask","body":"Fold the paper, draw one side, and cut. When you open it, both halves match. Your mask is symmetrical!","visual":"🎭"},{"title":"Look around","body":"Many things are symmetrical, like a butterfly, a leaf, a kite or the letter A. Some are not, like the letter F.","visual":"🍃"}],"questions":[{"kind":"mcq","prompt":"Avi could see with only one eye. What was wrong with his mask?","options":["His mask had too many colours","His mask was not symmetrical, so the eye holes did not match","His mask was too big","His mask was a cat"],"answer":1,"explain":"In a symmetrical mask, the two eye holes match on both sides."},{"kind":"mcq","prompt":"Which letter has two matching halves when you fold it down the middle?","options":["R","G","A","F"],"answer":2,"explain":"A is the same on both sides of a middle line. F, G and R are not."},{"kind":"numeric","prompt":"A symmetrical cat mask has 3 whiskers on the left half. How many whiskers are on the whole mask?","answer":6,"explain":"The right half also has 3, so 3 + 3 = 6."},{"kind":"mcq","prompt":"Which of these is symmetrical?","options":["a crumpled paper","a scribble","🦋 butterfly","a torn rag"],"answer":2,"explain":"A butterfly has matching wings on both sides."}]},{"id":"sk4","title":"The Mirror Game","icon":"🪞","kind":"lesson","story":"Soni and Avi play the mirror game with counters. A line is drawn in the middle!","teach":[{"title":"Mirror image","body":"Put a mirror on the line. Each counter on one side has a twin on the other side, the same distance from the line.","visual":"🪞"},{"title":"A mirror copies","body":"The painter used a mirror to get a full picture from half. A mirror shows a copy, but the copy is not real!","visual":"🖌️"}],"questions":[{"kind":"mcq","prompt":"The whole row is: 🔴⚪⚪⚪ | and then Avi's side. Which Avi side makes the whole row symmetrical?","options":["⚪⚪⚪🔴","⚪🔴⚪⚪","🔴⚪⚪⚪","⚪⚪🔴⚪"],"answer":0,"explain":"Avi's side must be Soni's side in reverse order, so the whole row matches on both sides."},{"kind":"mcq","prompt":"Soni's counter is 2 boxes from the line. Where must Avi put his mirror counter?","options":["1 box from the line","On the line","2 boxes from the line, on his side","4 boxes from the line"],"answer":2,"explain":"A mirror twin is the same distance from the line."},{"kind":"numeric","prompt":"Soni puts 4 counters on her side. Avi places 4 mirror counters. How many counters are there in all?","answer":8,"explain":"4 + 4 = 8."},{"kind":"mcq","prompt":"A painter puts a mirror next to a ₹100 note. You see two notes. How much money is real?","options":["₹100","₹0","₹300","₹200"],"answer":0,"explain":"The mirror only shows a copy. Only one real note is there."}]},{"id":"sk5","title":"Tiling the Paths","icon":"🧱","kind":"lesson","story":"Dada ji's foot got stuck in a gap between tiles. Help Soni and Avi tile the path properly!","teach":[{"title":"No gaps, no overlaps","body":"Good tiles cover the path with no gaps and no overlaps. Squares, rectangles and triangles fit well.","visual":"🟦"},{"title":"Repeat the tile","body":"You can join shapes to make your own tile. Then repeat the tile again and again to make a path.","visual":"🔁"}],"questions":[{"kind":"mcq","prompt":"Why did Dada ji's foot get stuck?","options":["The tiles were symmetrical","The tiles were too red","The path was too short","There was a gap between the tiles"],"answer":3,"explain":"Tiles should fit with no gaps."},{"kind":"mcq","prompt":"Which tile shape covers the floor with no gaps?","options":["Square","Circle","Round ball","Oval"],"answer":0,"explain":"Squares fit side by side. Round shapes leave gaps."},{"kind":"numeric","prompt":"A path has 3 rows of tiles. Each row has 5 tiles. How many tiles are there?","answer":15,"explain":"3 rows of 5 tiles is 5 + 5 + 5 = 15."},{"kind":"mcq","prompt":"A tile pattern repeats like this: 🟥🟦🟦🟥🟦🟦🟥 What tile comes next?","options":["🟦","🟨","🟥","🟩"],"answer":0,"explain":"The repeating part is red, blue, blue. After red comes blue."}]},{"id":"sk6","title":"Left, Right and Steps","icon":"🧭","kind":"lesson","story":"Avi and Soni play a clue game. Take steps forward, back, left and right to find the hidden prize!","teach":[{"title":"Direction words","body":"We use forward, back, left and right to tell the way. Count the steps too, like 2 steps to your right.","visual":"➡️"},{"title":"Guess the place","body":"To find a stall, use clues like near the kulfi cart, or the second stall from there.","visual":"🍦"}],"questions":[{"kind":"mcq","prompt":"You face the Giant Wheel. You turn right, then turn right again. Which way do you face now?","options":["Backward, the opposite way","Up in the sky","Still at the Giant Wheel","To your left side"],"answer":0,"explain":"Two right turns make half a turn, so you face the opposite way."},{"kind":"numeric","prompt":"Avi takes 6 steps forward and then 2 steps back. How many steps is he from where he began?","answer":4,"explain":"6 - 2 = 4 steps forward from the start."},{"kind":"numeric","prompt":"Soni takes 2 steps right, 5 steps forward and 3 steps more forward. How many steps does she walk in all?","answer":10,"explain":"2 + 5 + 3 = 10 steps."},{"kind":"mcq","prompt":"Stalls in a row: 🍦 🎈 🎎 🧸 🪁. Clue: it is the second stall after the kulfi cart. Which stall?","options":["🎎 puppets","🎈 balloons","🪁 kites","🧸 toys"],"answer":0,"explain":"After the kulfi cart, the first is balloons and the second is puppets."}]},{"id":"sk7","title":"Reading the Fair Map","icon":"🗺️","kind":"lesson","story":"Dada and Dadi are waiting at the chaupal! Soni and Avi must read the fair map to find them.","teach":[{"title":"Maps have signs","body":"A map uses pictures and names for places, like parking, ATM, restaurant, shops, pond and chaupal.","visual":"🗺️"},{"title":"Follow the lanes","body":"A map also shows lanes. Follow the lane, and turn left or right when the clues say so.","visual":"🛣️"}],"questions":[{"kind":"mcq","prompt":"On the fair map, which place does the sign 🏧 show?","options":["Parking","Restaurant","ATM","Pond"],"answer":2,"explain":"The 🏧 sign means an ATM, where you take out money."},{"kind":"numeric","prompt":"The map of the fair shows 1 Enter gate and 2 Exit gates. How many exit routes are there?","answer":2,"explain":"There are 2 exit gates, so 2 exit routes."},{"kind":"mcq","prompt":"Soni's lane goes: Entry, Pond, Restaurant, Chaupal. Which place is between the Pond and the Chaupal?","options":["Pond","Restaurant","Entry","Exit"],"answer":1,"explain":"The order is Entry, Pond, Restaurant, Chaupal. The Restaurant is in the middle."},{"kind":"numeric","prompt":"Soni walks 5 steps on the blue lane. She turns right and walks 3 steps on the green lane. How many steps in all?","answer":8,"explain":"5 + 3 = 8 steps."}]},{"id":"sk-boss","title":"The Fair Finale","icon":"🎪","kind":"boss","boss":{"name":"Mirror Maze Master","taunt":"Can you beat my maze of mirrors, tiles and maps?"},"story":"At the end of the fair, the Mirror Maze Master blocks the exit. Use all your fair skills to get out!","teach":[{"title":"Fair review","body":"Symmetry means matching halves. Tiles leave no gaps. Maps and direction words help us find the way.","visual":"🎪"}],"questions":[{"kind":"mcq","prompt":"Which mala is symmetrical?","options":["🟡🟡🟡🟡🔵🔵🔴🔴","🟡🔵🔴🟡🔵🔴🟡🔵","🔴🔴🔵🔵🟡🟡🔴🔵","🟡🔵🔴🟡🟡🔴🔵🟡"],"answer":3,"explain":"The left half matches the right half in reverse."},{"kind":"numeric","prompt":"A row of 7 boxes has 4 red and 3 blue. The row must be the same from both ends (a mirror). In how many ways can you do it?","answer":3,"explain":"The middle box is blue. Then 1 of the 3 pairs is blue, so there are 3 ways."},{"kind":"mcq","prompt":"Which shape fits as a tile with no gaps and no overlaps?","options":["Rectangle","Circle","Ball","Oval"],"answer":0,"explain":"Rectangles fit side by side. Round shapes leave gaps."},{"kind":"numeric","prompt":"A path has 4 rows with 6 tiles in each row. How many tiles are there?","answer":24,"explain":"4 rows of 6 tiles is 6 + 6 + 6 + 6 = 24."},{"kind":"numeric","prompt":"Avi takes 7 steps forward, 3 steps back and then 2 steps forward. How many steps is he from the start?","answer":6,"explain":"7 - 3 = 4, then 4 + 2 = 6 steps."},{"kind":"mcq","prompt":"Soni needs cash at the fair. Which place on the map should she look for?","options":["ATM","Parking","Play area","Pond"],"answer":0,"explain":"An ATM gives money."},{"kind":"numeric","prompt":"The painter charges ₹200. Soni pays with a ₹500 note. How many rupees does she get back?","answer":300,"explain":"500 - 200 = 300 rupees."}]}]}];